    displayWidthPx?: number;
    /** computer_20251124 / displayHeightPx. */
    displayHeightPx?: number;
    /** computer_20251124 / displayNumber (X11). */
    displayNumber?: number;
    /** computer_20251124 / enable_zoom. */
