/**
 * Plugin Skill Definitions
 *
 * Plugins contributing the `skills` capability ship agent skills through
 * their manifest. The discriminated `source` union covers five sourcing
 * modes: a plain SKILL.md folder, an Anthropic-managed container skill,
 * inline markdown, a bundle folder with sibling scripts/references/assets,
 * or a zipped bundle archive extracted at enable time.
 *
 * `local-folder` and `local-bundle` differ only in expectations — the
 * folder variant has historically been SKILL.md-only and stays
 * backward-compatible while now also surfacing sibling resources when they
 * exist; the bundle variant declares the resource-bearing layout
 * explicitly so the loader treats missing siblings as a soft warning
 * instead of silence. `archive` points at a `.zip` matching the Anthropic
 * skill-creator / Codex CLI superset format.
 */
type PluginSkillSource = {
    kind: "local-folder";
    path: string;
} | {
    kind: "anthropic-managed";
    containerSkillId: string;
    version?: string;
} | {
    kind: "inline";
    markdown: string;
} | {
    kind: "local-bundle";
    path: string;
} | {
    kind: "archive";
    path: string;
};
interface PluginSkillDef {
    /** Unique id within the plugin. */
    id: string;
    /** Display name shown in the skill picker. */
    name: string;
    /** One-line description. */
    description: string;
    /** Where the skill content comes from. */
    source: PluginSkillSource;
    /**
     * Visibility scope:
     * - "character": only appears in character-level skill picker
     * - "team":      only in team skill picker
     * - "global":    shows in every picker but never auto-attaches
     */
    scope?: "character" | "team" | "global";
    /** When set, the plugin pre-attaches the skill to these character ids on enable. */
    attachToCharacterIds?: string[];
    /** Optional allow-list of tools the skill needs. */
    allowedTools?: string[];
    /**
     * Runtime-only install directory used to bind plugin-root tokens when the
     * skill body is loaded. The host adds this during capability registration;
     * plugin manifests never need to provide it.
     */
    runtimePluginRoot?: string;
}

/**
 * Plugin Subagent Definitions.
 *
 * Plugins contributing the `subagent` capability ship Claude Code SDK
 * `AgentDefinition`-shaped entries through the manifest. The host registers
 * each entry into the `subagent-registry` overlay on enable and unregisters
 * on disable — identical lifecycle to `skills` / `mcp-server-preset`.
 *
 * Runtime resolution (see `lib/claude/agents/subagents/index.ts:resolveAllSubagents`)
 * unions the 4 host-bundled subagents (workflow-designer / workflow-debugger /
 * workflow-refactorer / workflow-doc-writer) with the plugin overlay. Plugin
 * subagent names are namespaced as `<pluginId>:<id>` at projection time so
 * they never collide with built-in dispatcher names.
 *
 * Fields mirror `AgentDefinition` in `lib/claude/agents/subagents/types.ts`
 * 1:1 — adding the `id` discriminator + display `name` is the only delta.
 * Kept narrow on purpose; broaden when a new manifest carries a field the
 * SDK actually consumes.
 */
/**
 * Subagent reasoning-effort dial. Mirrors the Claude Code SDK enum.
 */
type PluginSubagentEffort = "low" | "medium" | "high" | "xhigh" | "max";
/**
 * A subagent contributed by a plugin.
 */
interface PluginSubagentDef {
    /** Unique id within the plugin. Runtime id is `<pluginId>:<id>`. */
    id: string;
    /** Display name shown in the subagent picker. */
    name: string;
    /** Natural-language description shown to the dispatcher agent. */
    description: string;
    /** System prompt the subagent runs with. */
    prompt: string;
    /** Allowlist of tool names; omit to inherit the parent's tools. */
    tools?: string[];
    /** Tools to explicitly disallow. */
    disallowedTools?: string[];
    /** Model alias (`opus` / `sonnet` / `haiku`) or full id; defaults to the parent's model. */
    model?: string;
    /**
     * Provider id (`anthropic` / `openai` / `deepseek` / …) this subagent runs on.
     * When set AND configured, the subagent runs on this provider with its own
     * credentials — so a subagent can use a DIFFERENT provider than the parent
     * session (e.g. a DeepSeek chat delegating to a Claude reviewer). Pairs with
     * `model`; omit to inherit the parent's provider. An unconfigured provider
     * falls back to the parent's (so a stale id never breaks dispatch).
     */
    provider?: string;
    /** Max round-trips before the SDK stops looping the subagent. */
    maxTurns?: number;
    /** Reasoning effort dial. */
    effort?: PluginSubagentEffort;
    /**
     * Optional external-agent preset id backing this subagent (Thread A2). When
     * set, `dispatchSubagent` routes the run to the external CLI agent instead of
     * the built-in executor. `prompt` / `tools` remain advisory.
     */
    externalPresetId?: string;
    /**
     * MCP server ids/names to forward into the external agent's ACP session
     * (`session/new` `mcpServers`) when this subagent runs on an external preset.
     * Resolved through `resolveAcpMcpServers`; ignored for the built-in executor
     * (which inherits the parent session's MCP config). Only the explicitly-listed
     * enabled servers are forwarded — never "all".
     */
    mcpServerIds?: string[];
    /**
     * Opt this subagent into nested dispatch — i.e. when it runs, expose the
     * `dispatch_agent` tool so it can itself dispatch further subagents (up to the
     * effective depth cap). Default `false`: a subagent is a leaf unless it opts
     * in. Ignored unless app-level `subagentNesting.enabled` is on.
     */
    allowNesting?: boolean;
    /**
     * Per-subagent override of the max nesting level. The effective cap is
     * `min(appSettings.subagentNesting.maxDepth, this)`.
     */
    maxDepth?: number;
    /**
     * Hide from UI pickers / @-mention autocomplete while staying dispatchable
     * (OpenCode `hidden` semantics). Model-facing discovery is unaffected.
     */
    hidden?: boolean;
    /** Fully off: excluded from dispatch, discovery, and every picker. */
    disabled?: boolean;
}

/**
 * External Agent Type Definitions
 * Defines types for integrating external agents via ACP (Agent Client Protocol) and other protocols
 *
 * @see https://github.com/anthropics/agent-client-protocol
 * @see https://github.com/zed-industries/claude-code-acp
 */

/**
 * Supported external agent protocols
 */
type ExternalAgentProtocol = "acp" | "codex-app-server" | "dsh-sdk" | "pi-rpc" | "opencode" | "opencode-v2" | "a2a" | "http" | "websocket" | "custom";
/**
 * External agent transport mechanism
 */
type ExternalAgentTransport = "stdio" | "http" | "websocket" | "sse";
/**
 * Canonical runtime branch/block reason codes for external-agent routing and diagnostics.
 */
type ExternalAgentBranchReasonCode = "ok" | "agent_not_found" | "configuration_missing" | "agent_disabled" | "protocol_unsupported" | "transport_blocked" | "ecosystem_prerequisite_missing" | "ecosystem_documented_only" | "initialization_failed" | "health_check_failed" | "external_unavailable" | "extension_unknown" | "extension_unsupported" | "session_resolution_failed" | "permission_denied" | "execution_failed" | "strict_failure" | "fallback_to_builtin" | "runtime_version_unsupported" | "sandbox_unavailable" | "extension_handshake_failed" | "protocol_frame_invalid" | "resource_limit";
/**
 * Canonical branch outcome for external-agent orchestration.
 */
type ExternalAgentBranchOutcome = "external" | "fallback" | "strict_failure" | "builtin" | "blocked";
/**
 * Lifecycle completeness stages used by manager/store/UI diagnostics.
 */
type ExternalAgentLifecycleCompletenessStage = "config" | "connect" | "session_extensions" | "execution" | "fallback" | "recovery";
/**
 * Canonical execution eligibility state.
 */
type ExternalAgentExecutionEligibility = "eligible" | "blocked";
/**
 * Support tier for a product-level external-agent ecosystem surface.
 */
type ExternalAgentEcosystemSupportTier = "executable" | "guided" | "documented-only";
/**
