interface UsageInfo {
    inputTokens?: number;
    outputTokens?: number;
    /**
     * Authoritative tokens currently occupying the live context. External agents
     * such as Codex report this independently from per-turn billable usage.
     */
    contextTokens?: number;
    /** Authoritative live model context-window size, when the provider reports it. */
    contextWindow?: number;
    /**
     * Prompt tokens occupying the *current* context window after the turn, when
     * that differs from `inputTokens`. On the ai-sdk channel a turn runs a manual
     * agent loop of several legs, and `inputTokens` SUMS every leg's prompt (the
     * correct cumulative-billing figure, since the API re-charges each leg). The
     * window, however, holds only the LAST leg's prompt — so window math must use
     * this field when present. `undefined` on single-result channels (native
     * Anthropic), where `inputTokens` already equals the window prompt.
     */
    contextInputTokens?: number;
    cacheCreationInputTokens?: number;
    cacheReadInputTokens?: number;
    /**
     * Cache-creation tokens split by TTL, when the provider reports it. Anthropic
     * bills a 5-minute write at 1.25× base input and a 1-hour write at 2×, so the
     * two cannot share `cacheCreationInputTokens` without under-billing the
     * 1-hour case. `undefined` when the provider reports only the flat total.
     */
    cacheCreation5mInputTokens?: number;
    cacheCreation1hInputTokens?: number;
    /**
     * Server-side tool invocation counts (`usage.server_tool_use`), normalized to
     * bare tool names. These are billed per call independently of tokens — web
     * search is $10 per 1,000 requests — so a turn's cost is incomplete without
     * them. `undefined` when the provider reported none.
     */
    serverToolUse?: Record<string, number>;
    /**
     * Reasoning / "thinking" tokens reported separately by the provider (a subset
     * of output tokens, already billed at the output rate). Surfaced for
     * observability; `undefined` when the provider bundles thinking into output
     * (native Anthropic) or the model doesn't reason.
     */
    reasoningTokens?: number;
    totalCostUsd?: number;
    durationMs?: number;
}

/**
 * Run a Claude turn and capture the assistant's final reply text.
 *
 * Why this wrapper exists: the sidecar IPC `sendPrompt(...)` is fire-and-
 * forget — the assistant reply streams back as `claude://message` events.
 * The connector runtime needs the final text to enqueue an outbound
 * platform message, so it can't just call `sendPrompt` and hope. This
 * helper subscribes to the event channel before sending, accumulates
 * assistant content, and resolves with `{ text, messageId }` once the
 * session ends.
 *
 * Scope: this helper does NOT save the assistant message itself. The
 * existing renderer-side persistence (`hooks/chat/use-claude-chat.ts`)
 * already does that via the same event channel — both subscribers see
 * each event independently. The bridge only intercepts text for outbound
 * routing.
 *
 * Cancellation: pass an `AbortSignal` to abort early. On abort, an
 * `interruptSession` IPC is fired (best effort), the subscription briefly
 * drains the interrupted turn's terminal usage event, then detaches and rejects
 * with `AbortError`. Mirrors the `mode-switcher.tsx:invoke("claude_interrupt",
 * ...)` semantics without discarding tokens already billed by completed steps.
 */

/**
 * Typed incremental events surfaced from the SAME assistant-block parse loop
 * the capture already walks. Consumed by the plugin Agent SDK's `runStreamed`
 * so it doesn't have to re-parse `onClaudeMessage`. Best-effort: a throwing
 * callback is swallowed and never affects capture.
 */
type CaptureStreamEvent = {
    type: "text-delta";
    delta: string;
} | {
    type: "thinking-delta";
    delta: string;
} | {
    type: "commentary-delta";
    delta: string;
    messageId?: string;
    done?: boolean;
} | {
    type: "tool-summary";
    summary: string;
    toolCallIds: string[];
} | {
    type: "tool-call";
    toolName: string;
    input: Record<string, unknown>;
    /** The originating `tool_use` block id, when the SDK supplies one. A stable
     * per-call identity so consumers can pair a later `tool-result` exactly and
     * distinguish two concurrent calls with identical name+input. */
    id?: string;
} | {
    type: "tool-result";
    toolName: string;
    /** Tool arguments correlated from the originating `tool_use` block, when known. */
    input?: Record<string, unknown>;
    /** The `tool_use_id` this result answers, when known (see `tool-call.id`). */
    id?: string;
    result: unknown;
    isError?: boolean;
}
/**
 * Token/cost usage for the turn, surfaced from the SDK `result` message as it
 * streams. The native Anthropic sidecar emits `session_ended` WITHOUT a
 * `result` payload, so consumers that want live usage (the CLI TUI footer)
 * cannot rely on the resolved `RunAndCaptureResult.usage` alone — this event
 * delivers it from the in-stream result message instead.
 */
 | {
    type: "usage";
    usage: UsageInfo;
    /**
     * True for a MID-run per-assistant-message snapshot (not cumulative);
     * consumers that want a live figure SUM these and let the final
     * authoritative (non-partial) `result`-message usage replace the sum.
     * Absent/false = the end-of-turn authoritative usage.
     */
    partial?: boolean;
}
/**
 * A context-compaction boundary crossed mid-stream. Both dispatch paths emit
 * the same `system` / `compact_boundary` message — the generic AI-SDK path
 * (`sidecar/dispatch/ai-sdk.mjs`) when it summarizes older turns, and the
 * Anthropic Agent SDK when it auto/manually compacts. Surfaced here so the CLI
 * TUI can mark the boundary inline (the desktop renders it from the raw
 * `claude://message` event independently). `trigger` is `"manual"` for a
 * user-requested `/compact` and `"auto"` for the threshold-driven one.
 */
 | {
    type: "compact";
    trigger: "manual" | "auto";
    preTokens: number;
    postTokens: number;
};

/**
 * Canonical permission ceiling shared by direct agents, Agent Teams,
 * workflows, plugins, and external-agent sessions.
 *
 * Every nested execution may only narrow this surface; it must never widen it.
 */
interface AgentPermissionCeiling {
    permissionMode?: AcpPermissionMode;
    allowedTools?: string[];
    disallowedTools?: string[];
    mcpServers?: Array<{
        name: string;
        [key: string]: unknown;
    }>;
    sandboxPolicy?: SandboxResourcePolicy;
}

/**
 * A minimal, protocol-agnostic description of the permission surface an
 * external-agent session is allowed to touch. Both the team-dispatch path
 * (Thread A1) and the subagent-dispatch path (Thread A2) build one of these
 * for the *parent* context and (optionally) one for the *child* agent
 * definition, then derive the effective spec via
 * {@link deriveExternalSessionPermission}.
 *
 * The cascade rule mirrors OpenCode's `deriveSubagentSessionPermission` and
 * Goose's force-Auto behaviour: **a parent's restriction always cascades; a
 * child may only further-restrict, never escalate.**
 */
/** @deprecated Import `AgentPermissionCeiling` from `@/types/agent/permission-ceiling`. */
type ExternalSessionPermissionSpec = AgentPermissionCeiling;

/**
 * Plugin Agent SDK — per-run lifecycle hooks (ADR-0026 §Agent-SDK).
 *
 * Hooks let a plugin observe and shape its OWN agent runs around tool calls and
 * completion, mirroring the Claude Agent SDK's PreToolUse / PostToolUse / Stop
 * surface. They are supplied per-run via {@link PluginAgentRunOptions.hooks}
 * (not a global registry) so the lifetime is exactly the run.
 *
 * Dependency-free leaf: only references sibling `types/plugin` contracts. The
 * runtime in `lib/plugin/agent-sdk/` adapts these to the executor + capture
 * seams (`canUseTool` round-trip for PreToolUse, the tool-result observation /
 * review round-trip for PostToolUse).
 */

/**
 * Input handed to {@link PluginPostToolUseFn} after a tool returns. `input` is
 * the (possibly rewritten) tool arguments when the capture loop could correlate
 * them; it is `{}` when unavailable (e.g. native Anthropic tools whose call is
 * not surfaced to the renderer). `result` is the tool output the model is about
 * to see; `isError` flags an errored tool result.
 */
interface PluginPostToolUseInput {
    toolName: string;
    input: Record<string, unknown>;
    result: unknown;
    isError: boolean;
}
/**
 * Result of a {@link PluginPostToolUseFn}. Return `{ updatedToolOutput }` to
 * REWRITE the output the model sees (sanitize / redact). Omit or return void to
 * observe only. Rewrite is honored only where the tool result is materialized
 * in-process (the ai-sdk channel + in-process MCP tools); native Anthropic
 * tools (Bash/Read/Edit/Grep) are observe-only — see the SDK docs.
 */
interface PluginPostToolUseResult {
    updatedToolOutput?: unknown;
}
/** PostToolUse lifecycle hook. */
type PluginPostToolUseFn = (input: PluginPostToolUseInput, ctx: {
    signal?: AbortSignal;
}) => Promise<PluginPostToolUseResult | void> | PluginPostToolUseResult | void;
/** Input handed to {@link PluginStopFn} once a run completes (either channel). */
interface PluginStopInput {
    text: string;
    finishReason?: string;
    usage?: {
        inputTokens: number;
        outputTokens: number;
        totalTokens: number;
    };
    /** Which execution channel actually ran. */
    channel: "sidecar" | "text";
}
/** Stop lifecycle hook — fired exactly once when the run resolves. Observational. */
type PluginStopFn = (input: PluginStopInput, ctx: {
    signal?: AbortSignal;
}) => void | Promise<void>;
/**
 * Per-run lifecycle hooks. All optional.
 *
 * - `onPreToolUse` — fired before a tool runs; may deny or REWRITE the tool
 *   input. Reuses the same result contract as `canUseTool`. When both a
 *   `canUseTool` (tool-level then run-level) and `onPreToolUse` are present, the
 *   hook runs LAST and sees the already-rewritten input; any `deny` wins.
 * - `onPostToolUse` — fired after a tool returns; observe and optionally rewrite
 *   the output (see {@link PluginPostToolUseResult}).
 * - `onStop` — fired once the run completes, on BOTH channels (graceful
 *   degradation: tool hooks never fire on the text channel, but `onStop` does).
 */
interface PluginAgentHooks {
    onPreToolUse?: PluginToolPermissionFn;
    onPostToolUse?: PluginPostToolUseFn;
    onStop?: PluginStopFn;
}

/**
 * Plugin Agent SDK — input/output guardrails (ADR-0026 §Agent-SDK).
 *
 * Guardrails are validators that run AROUND a plugin agent run: input
 * guardrails before the turn (validate the prompt), output guardrails after
 * (validate the final text). A guardrail that trips its tripwire aborts the run
 * with a typed error. Mirrors the OpenAI Agents SDK guardrail primitive and
 * generalizes the PII gate.
 *
 * Dependency-free leaf. The runtime in `lib/plugin/agent-sdk/guardrails.ts`
 * executes these around `runPluginAgent` / `runPluginAgentStreamed`; the
 * `lib/plugin/registries/guardrail-registry.ts` overlay stores reusable ones a
 * plugin registers via `ctx.agent.guardrails`.
