/**
 * Network proxy configuration types.
 *
 * Surfaced under Settings → Network Proxy. The persisted shape lives on the
 * `AppSettings.networkProxy` field; the Rust side mirrors it via
 * `src-tauri/src/proxy_config/mod.rs:ProxyConfig` and reads it through
 * `proxy_apply` whenever the frontend writes a change.
 */
type ProxyProtocol = "http" | "https" | "socks5";
/**
 * `off` — no proxy applied.
 * `manual` — the user has filled in host/port (and optional auth) explicitly.
 * `auto` — auto-detected at startup or via the Detection tab; behaves the
 *   same as `manual` once a host/port is populated, but the
 *   `lastDetectedAt` timestamp distinguishes it for UX.
 */
type ProxyMode = "off" | "manual" | "auto";
interface NetworkProxySettings {
    mode: ProxyMode;
    protocol: ProxyProtocol;
    host: string;
    port: number;
    username?: string;
    /**
     * Hosts and CIDR ranges that should bypass the proxy. Matched as exact
     * hosts/IPs, leading-dot domain suffixes, or IPv4/IPv6 CIDR ranges.
     * Defaults to the loopback set so localhost dev servers always reach
     * directly.
     */
    bypass: string[];
    /** When false, WSS connections skip the proxy even when `mode !== "off"`. */
    proxyWebsockets: boolean;
    /** Epoch ms — populated whenever auto-detect successfully writes a host. */
    lastDetectedAt?: number;
    /**
     * Master switch for the IP-info panel (Settings → Network → IP). When
     * `false`, the app never contacts the public IP lookup endpoint
     * (`ipinfo.io`). Defaults to `true`; the lookup itself still honours the
     * active proxy + bypass list, so it reports the egress IP the proxy sees.
     */
    ipLookupEnabled: boolean;
}

/**
 * Permission scope for the MCP bridge — one knob per (capability × content)
 * combination, default OFF except `wiki:cognia` and `rag:cognia`. The Settings
 * UI renders one toggle per value here.
 */
type BridgeScope = "wiki:cognia" | "wiki:user-repo" | "rag:cognia" | "rag:user-repo"
/**
 * RAG over the user's digital twin chunks. Default OFF; users must opt in
 * explicitly because twin data is significantly more sensitive than the
 * generated wiki (it can contain personal documents, chat history, etc.).
 */
 | "rag:twin" | "runtime:skills" | "runtime:characters" | "runtime:twins" | "runtime:plugins" | "runtime:agent-teams"
/**
 * `computer_use` MCP tool — drives the local desktop (screenshot, click,
 * type, scroll, drag, etc.) for external coding agents. Default OFF; goes
 * through the same automation `PerCall` consent path as native chat
 * Computer Use calls.
 */
 | "mcp:computer-use"
/**
 * Read-only inbox introspection — list adapters, conversations, drafts,
 * audit. Default OFF; mirrors the `rag:twin` sensitivity-split precedent
 * because inbox metadata may include conversation handles, channel ids,
 * and recent message snippets.
 */
 | "inbox:connectors:read"
/**
 * Write-side inbox — `connectors_send_message` enqueues an AI reply via
 * the same `runConnectorDigestTurn` pipeline used by the in-app chat (PII
 * gate, policy eval, idempotency, outbound runner all stay in path).
 * Split from `read` so an operator can grant introspection without
 * accidentally enabling automated replies.
 */
 | "inbox:connectors:send"
/**
