type AccountVariant = "anthropic" | "codex" | "opencode-discovered" | "opencode-zen";

/**
 * Renderer-safe projection of `Account` — strips the secret bearer. Returned
 * by `subscription_list_accounts` so the account picker doesn't see any token
 * bytes unless the renderer explicitly fetches the full `Account` for an
 * edit dialog.
 */
interface AccountSummary {
    id: string;
    label?: string;
    provider: ProviderId;
    /**
     * Variant tag distinguishing OpenCode discovery rows from Zen rows:
     * "anthropic" | "codex" | "opencode-discovered" | "opencode-zen".
     */
    variant: AccountVariant;
    email?: string;
    plan?: string;
    /** 0 when not applicable (api_key / opencode-zen). */
    expiresAtMs: number;
    createdAtMs: number;
    lastUsedAtMs: number;
}

/** Passive vs probe sample lineage. */
type UsageSource = "passive" | "probe";
/** Top-level `anthropic-ratelimit-unified-status` value. */
type UsageStatus = "allowed" | "allowed_warning" | "rate_limited" | "unknown";
type RepresentativeClaim = "five_hour" | "seven_day";
interface UsageWindow {
    utilization: number;
    resetAt: number;
    status: string;
}
interface UsageSnapshot {
    fetchedAt: number;
    source: UsageSource;
    status: UsageStatus;
    representativeClaim: RepresentativeClaim | null;
    fiveHour: UsageWindow | null;
    sevenDay: UsageWindow | null;
    fallbackPercentage: number | null;
    overageDisabledReason: string | null;
    rawHeaders: Record<string, string>;
}
/** Anthropic-specific subscription settings (probe loop). */
interface AnthropicSubscriptionSettings {
    probeEnabled: boolean;
    visibleIntervalMs: number;
    idleIntervalMs: number;
    warnThresholdPct: number;
}
/**
 * Codex-specific subscription settings.
 *
 * Note there is no `preferDiscovered`: env injection requires an explicitly
 * adopted account (ADR-0025). Settings rows persisted before that flag was
 * removed may still carry it; it is inert, and nothing reads it.
 */
interface CodexSubscriptionSettings {
    /** Refresh the bearer ~5min before expiry instead of waiting for failure. */
    autoRefreshNearExpiry: boolean;
    /**
     * Background usage probing of the active Codex account's 5h/weekly windows
     * (parity with the Anthropic probe loop). Off by default — opt-in.
     */
    probeEnabled: boolean;
    /** Probe cadence while the page is foregrounded (default 5 min). */
    visibleIntervalMs: number;
    /** Probe cadence while the page is hidden / idle (default 30 min). */
    idleIntervalMs: number;
    /** Utilization percent at which a window meter flips to the warn state. */
    warnThresholdPct: number;
}

/** Normalized balance reading for one account at one point in time. */
interface BalanceSnapshot {
    fetchedAt: number;
    /** Adapter key, e.g. "deepseek" | "openrouter" | "siliconflow" | "moonshot". */
    providerKey: string;
    accountId: string;
    kind: "credit" | "quota" | "usage";
    currency?: string;
    total?: number;
    remaining?: number;
    used?: number;
    /** "USD" | "CNY" | "tokens" | "requests". */
    unit?: string;
    raw: Record<string, unknown>;
    /** Set when a query failed; kept so the UI can surface the error inline. */
    error?: string;
}
/** Fully-resolved inputs an adapter needs to build + parse a balance query. */
interface BalanceQuery {
    accountId: string;
    providerKey: string;
    baseUrl: string;
    token: string;
}
/** A GET-only HTTP request description (no body — balance APIs are all reads). */
interface BalanceRequestDescriptor {
    url: string;
    headers: Record<string, string>;
}
/** Pure, per-provider balance adapter. */
interface BalanceAdapter {
    key: string;
    matches(q: {
        providerKey?: string;
        baseUrl?: string;
    }): boolean;
    request(q: BalanceQuery): BalanceRequestDescriptor;
    parse(status: number, body: string, q: BalanceQuery): BalanceSnapshot;
}

/** A meter is either a resetting utilization window or a credit/quota balance. */
type LimitsMeterKind = "window" | "balance";
/**
 * Three-step severity plus two terminals. `ok`/`warn`/`crit` mirror the
 * Anthropic `UsageLevel` (crit once a window hits 100%); `exceeded` flags a
 * window past 100% or a non-positive balance; `unknown` is "no usable reading".
 */
type LimitsMeterStatus = "ok" | "warn" | "crit" | "exceeded" | "unknown";
/** One normalized meter on a provider account. */
interface LimitsMeter {
    /** Stable id within the snapshot, e.g. "session" | "weekly" | "weekly_sonnet" | "credit". */
    id: string;
    /**
     * i18n key the renderer resolves (no hard-coded strings reach the UI). Built-in
     * meters use keys under `subscription.limits.meter.*`; plugin meters may pass a
     * pre-resolved string here and set `label` instead.
     */
    labelKey?: string;
    /** Pre-resolved label for plugin/dynamic meters that don't have an i18n key. */
    label?: string;
    kind: LimitsMeterKind;
    /**
     * Utilization as a whole percent (0-100, may exceed 100 on overage). For a
     * `balance` meter this is `used/total*100` when `total` is known, else `null`.
     */
    usedPct: number | null;
    /** Epoch ms when a `window` meter resets, or `null`/absent for balances. */
    resetAt?: number | null;
    /** Balance amounts (when `kind === "balance"`). */
    used?: number;
    total?: number;
    remaining?: number;
    /** "USD" | "CNY" | "tokens" | "requests" — for balance meters. */
    unit?: string;
    /** ISO-4217 currency for credit meters ("USD" | "CNY"). */
    currency?: string;
    status: LimitsMeterStatus;
}
/** Normalized limits/usage reading for one subscription account at one instant. */
interface ProviderLimits {
    /** `ProviderId` for built-in sources; the balance providerKey for credit meters. */
    provider: string;
    /** Vault account id this snapshot describes (absent for ad-hoc readings). */
    accountId?: string;
    /** Account label for display headers, when known. */
    accountLabel?: string;
    fetchedAt: number;
    meters: LimitsMeter[];
    /** Set when the query failed; kept so the UI can surface the error inline. */
    error?: string;
}
/** Fully-resolved I/O + identity a `LimitsSource` needs to fetch one account. */
interface LimitsSourceContext {
    provider: ProviderId;
    accountId: string;
    accountLabel?: string;
    /** Bearer token for the account, or `null` when none is available. */
    token: string | null;
    /**
     * The account's stored credential, verbatim. Sources need it for identity a
     * bare bearer can't carry: Codex's `/wham/usage` is a ChatGPT-subscription
     * endpoint that requires the `ChatGPT-Account-Id` header and rejects an
     * `api_key` login outright, so the source must read `authMode`/`accountId`
     * rather than infer them from the preset. Absent when the runner couldn't
     * resolve the account.
     */
    credential?: ProviderCredential;
    /** Resolved preset baseUrl (for credit/host-matched sources). */
    baseUrl?: string;
    /** Resolved preset templateId (the authoritative provider-match signal). */
    providerKey?: string;
    /**
     * The resolved preset's `extraHeaders`, verbatim. Carries internal `x-cognia-*`
     * config a source may need but that never reaches the wire (e.g. the
     * Volcengine AccessKey ID / Secret for the SigV4 usage query). Absent when the
     * account has no preset.
     */
    presetHeaders?: Record<string, string>;
    /**
     * CORS-free authed GET. Tauri injects `subscription_authed_get`; the CLI
     * injects a node-`fetch`-backed implementation. Sources that fetch their own
     * way (e.g. the Anthropic header probe) may ignore it.
     */
    authedGet: (url: string, headers?: Record<string, string>) => Promise<string>;
    /**
     * Refresh the account's bearer and return the new token (or `null` if refresh
     * isn't possible / failed). Injected by the runner for OAuth providers whose
     * access token expires (Anthropic); a source calls it once on an auth failure
     * and retries. Absent for token/key providers that never expire.
     */
    refreshToken?: () => Promise<string | null>;
    /** Injected clock for reset-countdown math. */
    now: number;
}
/**
 * Pure-ish per-provider limits source. `matches` is pure; `fetch` performs the
 * (injected) I/O and returns a normalized snapshot, `null` when the source
 * doesn't apply to the account (the runner then falls through to the next
 * candidate), or a snapshot with `error` set on a failed query.
 */
interface LimitsSource {
    key: string;
    matches(q: {
        provider?: string;
        providerKey?: string;
        baseUrl?: string;
    }): boolean;
    fetch(ctx: LimitsSourceContext): Promise<ProviderLimits | null>;
}

/** How a reset timestamp is encoded in the provider response. */
type ResetUnit = "unix" | "ms" | "iso" | "relativeSeconds";
/**
 * Pick one element out of a discriminated array before reading a window's paths.
 * Lets each window pull from a different element — e.g. Zhipu's `data.limits[]`,
 * where each entry is tagged `TOKENS_LIMIT: "five_hour" | "weekly"` and the
 * engine selects the entry whose tag matches this window's tier.
 */
interface WindowSelect {
    /** Dot-path to the array to search, e.g. "data.limits". */
    arrayPath: string;
    /** Field within each element whose value identifies it, e.g. "TOKENS_LIMIT". */
    by: string;
    /** Value that element's `by` field must equal, e.g. "five_hour". */
    equals: string | number;
}
/** One window inside a `window`-kind descriptor (utilization that resets). */
interface WindowSpec {
    /** Meter id within the snapshot, e.g. "session" | "weekly". */
    id: string;
    /** i18n key the renderer resolves (built-ins under `subscription.limits.meter.*`). */
    labelKey: string;
    /**
     * Dot-path to a pre-computed utilization value (a percent unless `usedPctScale`
     * rescales it). Optional: when omitted, the engine derives utilization from the
     * `usedPath`/`totalPath` (or `remainingPath`/`totalPath`) counts below.
     */
    usedPctPath?: string;
    /**
     * Multiply the raw value before use, e.g. a provider reporting a 0–1 fraction
     * uses `usedPctScale: 100`. Defaults to 1.
     */
    usedPctScale?: number;
    /**
     * When the provider reports *remaining* percent instead of *used*, set this so
     * the engine stores `100 - value`. Applied after `usedPctScale`.
     */
    invert?: boolean;
    /**
     * Count-based alternative to `usedPctPath`: derive utilization from
     * `usedPath / totalPath` (or, when `usedPath` is absent, `1 - remainingPath /
     * totalPath`). Used by Coding Plan providers that report request/token counts
     * rather than a pre-computed percentage (MiniMax, Kimi-coding).
     */
    usedPath?: string;
    /** Dot-path to the window's total/count capacity (pairs with `usedPath`). */
    totalPath?: string;
    /** Dot-path to the window's remaining count (used when `usedPath` is absent). */
    remainingPath?: string;
    /**
     * Select a specific array element before reading this window's paths. Each
     * window can select independently, so a discriminated array yields one meter
     * per tier (see `WindowSelect`).
     */
    select?: WindowSelect;
    /** Dot-path to the reset timestamp (interpreted per `resetUnit`). */
    resetAtPath?: string;
    resetUnit?: ResetUnit;
    /**
     * Dot-path to a window length in seconds (e.g. 18000=5h, 604800=7d). When
     * present and no `id` override is wanted, the engine can map it to a tier
     * label — but `id`/`labelKey` always win. Kept for parity with providers that
     * report `limit_window_seconds` instead of a stable window name.
     */
    windowSecondsPath?: string;
}
/** Extract a resetting utilization window (or several). */
interface WindowExtract {
    kind: "window";
    windows: WindowSpec[];
}
/** Extract a credit/quota balance. */
interface BalanceExtract {
    kind: "balance";
    totalPath?: string;
    usedPath?: string;
    remainingPath?: string;
    /** Display unit, "USD" | "CNY" | "tokens" | "requests". */
    unit?: string;
    /** ISO-4217 currency for credit meters. */
    currency?: string;
    /**
     * Multiply raw amounts by this before display (e.g. Novita reports 1/10000
     * USD → scale 0.0001). Defaults to 1.
     */
    scale?: number;
}
type DescriptorExtract = WindowExtract | BalanceExtract;
/** A declarative limits/usage source. */
interface SourceDescriptor {
    /** Stable id (also the resulting `LimitsSource.key`). */
    id: string;
    /** Provider-match signals. At least one should be set or it matches nothing. */
    match: {
        /**
         * Exact preset `templateId` / provider key, e.g. "stepfun". An array matches
         * any of the listed keys (a provider shipped under several catalog ids, e.g.
         * "glm" plus the "glm-anthropic" relay).
         */
        providerKey?: string | string[];
        /**
         * Substring(s) the account's resolved baseUrl must contain, e.g.
         * "stepfun.com". An array matches when the baseUrl contains ANY entry (a
         * provider reachable on several hosts, e.g. Zhipu's CN "bigmodel.cn" and
         * international "z.ai").
         */
        baseUrlIncludes?: string | string[];
    };
    request: {
        /**
         * Path appended to the resolved base. Supports `{{...}}` placeholders. When
         * `useBaseUrlOrigin` is set the base is the preset URL's scheme+host origin;
         * otherwise it is the full trimmed preset baseUrl.
         */
        path: string;
        /**
         * Build the request URL from the preset baseUrl's ORIGIN (scheme + host)
         * rather than its full path. Set this for quota/balance endpoints whose path
         * is fixed at the host root but whose preset baseUrl carries an unrelated
         * path segment (e.g. an `.../api/anthropic` relay preset, or an `.../v1`
         * chat base). `path` must then be absolute-from-origin (e.g.
         * "/api/monitor/usage/quota/limit"). Defaults to `false` (append to the full
         * baseUrl — used by providers whose usage path is relative to the base).
         */
        useBaseUrlOrigin?: boolean;
        method?: "GET";
        /**
         * Extra headers; values support `{{token}}`/`{{baseUrl}}`/`{{accountId}}`.
         * Provide an `Authorization` header to override the default
         * `Bearer {{token}}` (e.g. Zhipu uses the raw key with no scheme; New-API
         * relays add a `New-Api-User` header alongside the bearer).
         */
        headers?: Record<string, string>;
    };
    extract: DescriptorExtract;
}
/**
 * A user-defined source: a self-contained descriptor that carries its own
 * endpoint + token (it has no vault account). Stored in app settings and run by
 * the custom runner; surfaced as its own provider block.
 */
interface CustomLimitsSource {
    /** UUID-ish stable id. */
    id: string;
    /** User-facing name shown as the provider header. */
    name: string;
    /** Endpoint host the `request.path` is appended to. */
    baseUrl: string;
    /** Bearer token (stored in the renderer settings store — see security note). */
    token: string;
    /** Network access is opt-in. Missing is treated as disabled for legacy rows. */
    enabled?: boolean;
    /** Preferred automatic refresh cadence imported from external managers. */
    refreshIntervalMs?: number;
    request: SourceDescriptor["request"];
    extract: DescriptorExtract;
}

/**
 * Targets a CCSwitch provider switch can propagate into. A superset of the
 * modeled `AgentId` union plus `"opencode"` — OpenCode is a propagation
 * target (we write its `auth.json`) but is not one of cognia's modeled
 * agents, so it is added here rather than to the global `AgentId`.
 */
type CcswitchAgentId = AgentId | "opencode";

/** How much of a URL a chip should show. */
type LinkDisplayStyle = "short" | "host" | "full";

/**
 * Composer skins — the table that decides how the input box is arranged.
 *
 * A skin is data, not a component. It resolves to a handful of CSS custom
 * properties plus three layout enums, which `ComposerBox` consumes; there is no
 * per-skin fork of the render tree. Adding a sixth skin is one row in
 * {@link COMPOSER_SKINS} plus two i18n keys.
 *
 * ## The invariant: reachability, not visibility
 *
 * A skin decides WHERE each control sits — inline, on a rail, or folded behind
 * the toolbar's "⋯" disclosure. It never removes one. `focus` is allowed to
 * fold more than the others; it is not allowed to drop a control on the floor.
 * `bottom-toolbar.tsx` already owns that disclosure, so "folded" is an existing
 * mechanism a skin selects, not one it authors.
 *
 * ## `classic` is preserved by construction
 *
 * `classic` is today's composer. It deliberately carries NO token values: the
 * box branches on the id and renders its original literal Tailwind classes, so
 * "unchanged" does not depend on anyone getting a rem→px conversion right. See
 * `composer-box.tsx` and the parity test beside it.
 */
/** Stable ids. `classic` is the default and must stay first. */
declare const COMPOSER_SKIN_IDS: readonly ["classic", "airy", "dense", "full", "focus", "sharp"];
type ComposerSkinId = (typeof COMPOSER_SKIN_IDS)[number];
/**
 * Where the status toolbar sits, and how much of its roster is spelled out.
 *
 *  - `detached`  — below the box (today's wide desktop layout)
 *  - `embedded`  — inside the box, tail packed into "⋯"
 *  - `rail`      — inside the box as a quiet monospace status line
 *  - `expanded`  — inline, every chip labelled, plus an ambient cost/context rail
 *  - `folded`    — only the model glyph inline; everything else behind "⋯"
 */
type ComposerToolbarLayout = "detached" | "embedded" | "rail" | "expanded" | "folded";
/** Shape of the send/stop control. */
type ComposerSendShape = "circle" | "rounded";
/** User overrides layered on top of the chosen preset. All optional. */
interface ComposerSkinOverrides {
    radiusPx?: number;
    padXPx?: number;
    padYPx?: number;
    mono?: boolean;
    sendShape?: ComposerSendShape;
    toolbarLayout?: ComposerToolbarLayout;
}

type CaptureMode = "confirm" | "silent" | "manual";
interface CaptureSettings {
    /** Master switch for clipboard watching + capture. */
    enabled: boolean;
    /**
     * `confirm` shows a bubble with a countdown; `silent` auto-saves with a
     * toast; `manual` only captures on an explicit action (no clipboard watch).
     */
    mode: CaptureMode;
    /** Clipboard poll interval (ms). 0 disables polling. */
    pollIntervalMs: number;
    /** Seconds before the confirm bubble auto-dismisses. */
    confirmTimeoutSec: number;
    /** When true, capture is suspended (nothing read or stored). */
    privacyMode: boolean;
}

type RadarScheduleMode = "off" | "daily" | "weekly" | "custom";
interface RadarScheduleSettings {
    mode: RadarScheduleMode;
    /** Required when `mode === "custom"`. 5-field cron. */
    customCron?: string;
    /** Optional IANA timezone. */
    timezone?: string;
}
interface RadarSettings {
    /** Master switch for auto-generation + pet teasers. */
    enabled: boolean;
    /** Minimum days between auto reports (skip if the last one is newer). */
    intervalDays: number;
    /** Activity window (days) to analyze. */
    windowDays: number;
    /** Cron schedule for background generation. */
    schedule?: RadarScheduleSettings;
}

/**
 * Types + config resolution for project instruction-file loading
 * (CLAUDE.md / AGENTS.md / AGENT.md) injected into the built-in agent's
 * system prompt. See ADR / the `lib/claude/instructions/` module README.
 */

/** How the directory tree is walked when collecting instruction files. */
type InstructionMode = "layered" | "nearest";
/** User-facing config (all optional — see {@link resolveInstructionsConfig}). */
interface InstructionsConfig {
    /** Master switch. Default `true`. */
    enabled?: boolean;
    /**
     * `"layered"` (Claude Code) collects every instruction file from the project
     * root down to cwd; `"nearest"` (opencode) stops at the first ancestor dir
     * that has one. Default `"layered"`.
     */
    mode?: InstructionMode;
    /** Load a global user-level instruction file. Default `true`. */
    includeGlobal?: boolean;
    /** Explicit global file path. When unset and `includeGlobal`, `~/.cognia/AGENTS.md` is tried. */
    globalPath?: string;
    /** Same-dir filename precedence. Default {@link DEFAULT_INSTRUCTION_FILE_NAMES}. */
    fileNames?: string[];
    /** opencode-style extra instruction paths/globs (relative to cwd or a root). */
    extraPaths?: string[];
    /** Per-file byte cap before truncation. Default 64000. */
    maxFileBytes?: number;
    /** Total file cap. Default 50. */
    maxFiles?: number;
    /** `@import` recursion depth. Default 5. */
    maxImportDepth?: number;
    /** Discover `.cognia/agents/*.md` project subagents. Default `true`. */
    loadProjectAgents?: boolean;
}

/** All-optional partial as stored on `AppSettings.gitSettings.panel`. */
type PartialSourceControlPanelPrefs = Partial<{
    diffView: string;
    ignoreWhitespace: boolean;
    confirmDiscard: boolean;
    confirmForcePush: boolean;
    smartCommit: boolean;
    postCommit: string;
    pullRebase: boolean;
    fetchPrune: boolean;
    autoFetch: boolean;
    autoFetchIntervalMinutes: number;
    branchSort: string;
    defaultTimelineView: string;
}>;

/**
 * Wire types for the Source Control seam — mirror the Rust DTOs in
