    lowPower?: boolean;
    /** Follow the local pointer/cursor with the pet's gaze. Defaults to true. */
    gazeFollowing?: boolean;
    /**
     * Opt-in LLM speak for the talk interaction (`speakAsPet` side channel).
     * Absent or `enabled: false` → talk shows a template bubble only; the pet
     * never spends a token. Mirrors the `labelSummary` utility-config pattern:
     * optional provider/model override, resolved by `buildUtilityLlmClient`.
     */
    llmSpeak?: UtilityModelConfig;
    /** Proactive speech preferences. Absent = defaults (disabled). */
    proactive?: PetProactiveSettings;
    /** Ambient twin-awareness preferences. Absent = defaults (disabled). */
    twinAwareness?: PetTwinAwarenessSettings;
    /**
     * Pet conversation memory (rolling history fed back into the prompt).
     * Absent = enabled — turning it off stops recording AND injecting history.
     */
    petMemory?: {
        enabled: boolean;
    };
    /**
     * Gentle Notification Center alert when the pet first becomes unwell from
     * sustained neglect. Absent = enabled; turning it off keeps the visual
     * condition + recovery but suppresses the notification.
     */
    careAlerts?: boolean;
    /** Optional sound effects (default OFF). */
    sound?: PetSoundSettings;
    /**
     * User-authored catchphrases mixed into the template bubble pool. Absent /
     * empty = template bubbles only. Each is shown verbatim (already the user's
     * words), so they're never sent through i18n.
     */
    customBubbles?: string[];
}

/**
 * Unified Language Server Protocol (LSP) configuration types.
 *
 * This is the single authoritative shape for an LSP server across BOTH
 * subsystems that previously each owned a divergent copy:
 *
 *   - the agent runtime LSP (`sidecar/lsp/*`), which previously hard-coded
 *     its server list, and
 *   - the editor LSP (`lib/plugin/lsp/*` + `lib/plugin/vscode-shim/*`),
 *     which carried `UserLspServerEntry` (settings) and `PluginLspServerDef`
 *     (plugin manifest) as two near-identical interfaces.
 *
 * `UserLspServerEntry` (`lib/claude/types.ts`) and `PluginLspServerDef`
 * (`types/plugin/plugin.ts`) are now aliases of {@link LspServerConfig} so the
 * shape lives in exactly one place. The resolver in
 * `lib/lsp/resolve-config.ts` layers builtin defaults ← user global settings ←
 * project-local `.cognia/lsp.json` into {@link ResolvedLspServer}[], and that
 * single resolved list drives both the agent sidecar (via `sendOptions.lsp`)
 * and the editor registry.
 */
/** Where a resolved server entry originated, in increasing override priority. */
type LspServerSource = "builtin" | "plugin" | "user" | "project";
/** Transport for talking to the spawned server. */
type LspTransport = "stdio" | "socket";
/**
 * One declarative Language Server definition. The same shape is authored by
 * builtin defaults, plugin manifests, user settings, and project-local
 * config files — the resolver merges them by `id`.
 */
interface LspServerConfig {
    /**
     * Stable id. Builtin ids (`"typescript"`, `"pyright"`, `"rust-analyzer"`,
     * `"gopls"`) can be re-declared by a higher layer to override/extend the
     * default; otherwise an id is unique within its layer.
     */
    id: string;
    /** Display name shown in Settings → Language Servers. */
    name: string;
    /**
     * Monaco language ids this server handles (e.g. `["typescript"]`). Used by
     * the editor LSP registry to select a provider for a model.
     */
    languages: string[];
    /**
     * File extensions (with leading dot, e.g. `".ts"`) the agent runtime LSP
     * matches a file against. Required on builtin entries; optional on user
     * entries that only target the editor.
     */
    extensions?: string[];
    /** Exact file-name matches (e.g. `["Dockerfile"]`), agent-side. */
    filenames?: string[];
    /**
     * Binary to spawn. Relative paths resolve against the install dir (plugin)
     * or are PATH-probed (builtin). Supports `${workspaceFolder}` substitution.
     */
    command: string;
    /** CLI arguments. Supports `${workspaceFolder}` substitution. */
    args?: string[];
    /** Environment variables merged onto the spawned process env. */
    env?: Record<string, string>;
    /**
     * Project-root marker files. The agent runtime walks up from a touched
     * file toward cwd and starts the server at the nearest directory holding
     * one of these (e.g. `["Cargo.toml"]`).
     */
    rootMarkers?: string[];
    /**
     * Markers that, when found closer to the file, disable this server for
     * that tree (e.g. `["deno.json"]` lets the Deno toolchain win over
     * tsserver).
     */
    excludeRootMarkers?: string[];
    /** Transport. Socket endpoints must be loopback-only. */
    transport?: LspTransport;
    /** Required for `socket`; for example `tcp://127.0.0.1:5007`. */
    endpoint?: string;
    /** Forwarded verbatim as LSP `initializationOptions`. */
    initializationOptions?: Record<string, unknown>;
    /**
     * Server-specific configuration returned for `workspace/configuration`
     * pull requests and pushed via `workspace/didChangeConfiguration`
     * (e.g. `{ "rust-analyzer": { "cargo": { "features": "all" } } }`).
     */
    settings?: Record<string, unknown>;
    /**
     * When `true`, the editor registry materialises a real on-disk workspace
     * (via `lsp-workspace-manager`) before spawning. Required for servers that
     * read the filesystem (rust-analyzer, gopls, pylsp).
     */
    workspaceFolderRequired?: boolean;
    /** When `false`, the resolver drops this entry (and any same-id default). Default true. */
    enabled?: boolean;
    /**
     * npm-provisioning metadata. When the `command` binary is missing, the
     * installer (`sidecar/vscode-ext-host/src/lsp-installer.ts`) can fetch the
     * package into the managed install dir (`<appData>/lsp/node/<pkg>/`) and
     * resolve `command` from its `node_modules/.bin`. Servers without this
     * field are detect-only (PATH probe, no auto-install).
     */
    install?: {
        /** npm package that ships the binary (e.g. `"vscode-langservers-extracted"`). */
        npmPackage: string;
        /** Pinned version/range. Defaults to `latest`. */
        version?: string;
    };
    /**
     * Milliseconds to wait for the server's `initialize` response before the
     * spawn is treated as failed (default 10 000). Guards against hung
     * binaries blocking the editor/agent forever.
     */
    startupTimeout?: number;
    /** Maximum aggregate RSS for the detached language-server process tree. */
    memoryLimitMb?: number;
}
/**
 * A {@link LspServerConfig} after the resolver merges every layer, tagged
 * with provenance for the UI and audit log.
 */
interface ResolvedLspServer extends LspServerConfig {
    /** The highest-priority layer that contributed to this entry. */
    source: LspServerSource;
    /**
     * When a lower-priority layer was overridden by `source`, the lower
     * layer's source (e.g. a `"user"` entry overriding a `"builtin"` default
     * records `overriddenBy: "user"` on the surviving entry). Used by the
     * settings UI to show "overrides builtin".
     */
    overriddenBy?: LspServerSource;
}
/**
 * First-class `AppSettings.lsp` slice. Replaces the former
 * `DeveloperSettings.userLspServers` / `DeveloperSettings.unsignedLspAllowed`
 * fields (migrated in `lib/lsp/migrate-settings.ts`).
 */
interface LspSettings {
    /** User-authored servers, including overrides of builtin defaults by id. */
    servers: LspServerConfig[];
    /**
     * Master toggle for the whole LSP subsystem (agent tools + editor).
     * Defaults to the legacy `builtinTools.lsp` semantics when undefined.
     */
    enabled?: boolean;
    /**
     * Dev-only: allow unsigned plugin LSP binaries to spawn after a single
     * in-session consent prompt. Migrated from `developer.unsignedLspAllowed`.
     */
    unsignedAllowed?: boolean;
    /**
     * Allow the install ladder to `npm install` a missing server into the
     * managed dir. Default true; the `COGNIA_DISABLE_LSP_DOWNLOAD` env var is
     * the hard override checked inside the sidecar.
     */
    autoInstall?: boolean;
}
/**
 * The LSP slice attached to `SendOptions.lsp` and consumed by the agent
 * sidecar (`sidecar/lsp/*`). The sidecar is a separate Node project that
 * cannot import `lib/` or `@/types`, so the renderer resolves the merged
 * server list and serialises it here.
 */
interface LspSendOptions {
    enabled: boolean;
    servers: ResolvedLspServer[];
    /** Allow the agent runtime's install ladder to npm-install missing servers. */
    autoInstall?: boolean;
    /** Managed install root (`<appData>/lsp`), resolved by the renderer. */
    installDir?: string;
}

/**
 * Compression type definitions for chat context management
 *
 * Provides types for:
 * - Compression strategies (summary, sliding-window, selective, hybrid)
 * - Compression settings (global and per-session)
 * - Compression state and metadata
 * - Compression triggers (manual and automatic)
 */
/**
 * Available compression strategies
 * - summary: Summarize older messages into a concise summary
 * - sliding-window: Keep only the most recent N messages
 * - selective: Keep important messages (system, key exchanges) and summarize others
 * - hybrid: Combination of sliding window for recent + summary for older
 * - recursive: Chunk-based recursive summarization for very long conversations
 * - optical: Render older messages to compact image frames a vision model reads
 *   back (optical / "text-as-image" compression, ADR-0063). Falls back to a
 *   text summary when the transcript is unrenderable or the round-trip fails.
 */
type CompressionStrategy = "summary" | "sliding-window" | "selective" | "hybrid" | "recursive" | "optical";
/**
 * Shape + budget knobs for the "optical" strategy (ADR-0063). All optional; the
 * sidecar renderer supplies defaults for anything omitted. Serialised verbatim
 * onto `ResolvedCompaction.optical` for the generic (AI-SDK) path.
 */
interface OpticalCompactionOptions {
    /** Frame edge in px (also bounds the glyph grid rows). Default 1024. */
    size?: number;
    /** Bundled bitmap font. Default "8x8" (the eval-winning square unscii cell). */
    font?: "8x8" | "5x8";
    /** Ink variant: six-hue sentence cycling, or plain black. Default per model. */
    variant?: "sent" | "bw";
    /** Target cell advance/pitch in px (differing from the font cell stretches). */
    cellWidth?: number;
    cellHeight?: number;
    /** 1 = row-major grid, 2 = two-column "doc" layout. Default 1. */
    columns?: 1 | 2;
    /** Print each line N times (redundancy coding). Default 1. */
    lineRepeat?: number;
    /** Max image frames before falling back to a text summary. Default 4. */
    maxFrames?: number;
    /** Min renderable-character fraction to attempt optical (else text). Default 0.7. */
    minCoverage?: number;
    /** Min token savings vs. text required to keep the optical archive. Default 0.15. */
    minSavings?: number;
    /** Run a one-shot vision round-trip readability check before keeping. Default true. */
    verify?: boolean;
    /** Min word-recall from the round-trip to keep the frame (0..1). Default 0.6. */
    readabilityThreshold?: number;
}
/**
 * Trigger modes for automatic compression
 * - token-threshold: Trigger when total tokens exceed threshold percentage
 * - message-count: Trigger when message count exceeds threshold
 * - manual: Only compress when user explicitly requests
 */
type CompressionTrigger = "token-threshold" | "message-count" | "manual";
/**
 * Model configuration for compression summarization
 */
interface CompressionModelConfig {
    /** Provider to use for summarization (defaults to current session provider) */
    provider?: string;
    /** Model to use for summarization (defaults to fast tier model) */
    model?: string;
    /** Max tokens for summary output */
    maxSummaryTokens?: number;
}
/**
 * Global compression settings stored in settings store
 */
interface CompressionSettings {
    /** Enable/disable compression globally */
    enabled: boolean;
    /** Compression strategy to use */
    strategy: CompressionStrategy;
    /** Trigger mode for automatic compression */
    trigger: CompressionTrigger;
    /** Token threshold percentage (0-100) to trigger compression */
    tokenThreshold: number;
    /** Message count threshold to trigger compression */
    messageCountThreshold: number;
    /** Number of recent messages to always preserve uncompressed */
    preserveRecentMessages: number;
    /** Always preserve system messages */
    preserveSystemMessages: boolean;
    /** Target compression ratio (0.1 to 0.9) for summary strategy */
    compressionRatio: number;
    /** Model configuration for summarization */
    compressionModel: CompressionModelConfig;
    /** Show notification when compression is triggered */
    showCompressionNotification: boolean;
    /** Allow user to undo/restore compressed messages */
    enableUndo: boolean;
    /** Minimum importance score (0-1) to keep a message during selective compression */
    importanceThreshold: number;
    /** Use AI-powered summarization when provider is available */
    useAISummarization: boolean;
    /** Preserve tool call metadata (name, args, status) when compressing tool results */
    preserveToolCallMetadata: boolean;
    /** Maximum tokens for individual tool call results before truncation */
    maxToolResultTokens: number;
    /** Number of messages per chunk for recursive compression */
    recursiveChunkSize: number;
    /** Retained threshold percentage (0-100) — the "drain line" after compression (dual-threshold) */
    retainedThreshold: number;
    /** Enable prefix stability mode to preserve KV cache across turns */
    prefixStabilityMode: boolean;
    /**
     * Active compaction-strategy id. `undefined` → the built-in strategy.
     * Plugin-contributed strategies register as `${pluginId}:${id}` (see the
     * `compaction-strategy` plugin capability). Resolved at `resolveSendOptions`
     * time into the summary prompt / keepRecent / fraction sent to the sidecar.
     */
    strategyId?: string;
    /**
     * Free-form "compact instructions" (Claude Code's `# Compact instructions`
     * parity). Merged into the summarization prompt so the user can steer what a
     * compaction preserves (e.g. "focus on the API changes"). Also seeds the
     * default focus for a manual `/compact` with no explicit argument.
     */
    focus?: string;
    /**
     * Shape + budget knobs for the "optical" strategy (only consulted when
     * `strategy === "optical"`). Absent ⇒ the sidecar renderer's own defaults.
     */
    optical?: OpticalCompactionOptions;
}
/**
 * Per-session compression overrides
 */
interface SessionCompressionOverrides {
    /** Override global compression enabled setting */
    compressionEnabled?: boolean;
    /** Override compression strategy for this session */
    compressionStrategy?: CompressionStrategy;
    /** Override trigger mode */
    compressionTrigger?: CompressionTrigger;
    /** Override token threshold */
    tokenThreshold?: number;
    /** Override message count threshold */
    messageCountThreshold?: number;
    /** Override preserve recent messages count */
    preserveRecentMessages?: number;
}

/** `plugins` entry. Paths are canonicalised and root-checked host-side. */
interface ClaudeAgentSdkPluginRef {
    type: "local";
    path: string;
    skipMcpDiscovery?: boolean;
}
/**
 * Sandbox settings, layered ON TOP of the sidecar's own workspace confinement
 * (`builtin-tools/confinement.mjs`) rather than replacing it. Two independent
 * gates is the intent: the SDK sandbox constrains the subprocess, confinement
 * constrains the tools Cognia itself serves.
 */
interface ClaudeAgentSdkSandboxV1 {
    enabled?: boolean;
    /** Refuse to run rather than silently continuing unsandboxed. */
    failIfUnavailable?: boolean;
    autoAllowBashIfSandboxed?: boolean;
    allowUnsandboxedCommands?: boolean;
    network?: {
        allowedDomains?: string[];
        deniedDomains?: string[];
        strictAllowlist?: boolean;
        allowLocalBinding?: boolean;
        allowUnixSockets?: string[];
        allowAllUnixSockets?: boolean;
    };
    filesystem?: {
        allowRead?: string[];
        denyRead?: string[];
        allowWrite?: string[];
        denyWrite?: string[];
        disabled?: boolean;
    };
    credentials?: {
        /** Deny-listed credential FILES — paths only, never contents. */
        files?: Array<{
            path: string;
            mode: "deny";
        }>;
        /** Env vars the sandbox hides or masks. Names only, never values. */
        envVars?: Array<{
            name: string;
            mode: "deny" | "mask";
            injectHosts?: string[];
        }>;
        allowPlaintextInject?: boolean;
    };
    excludedCommands?: string[];
}
/**
 * Descriptor for the SDK `sessionStore`. The store itself is a live object with
 * `append` / `load` methods and is built in the sidecar against the Rust host
 * (ADR-0090: host_rpc, so headless and companion get it for free).
 *
 * `backend` is an enum, not a path: a renderer must not be able to name where
 * session data lands.
 */
interface ClaudeAgentSdkSessionStoreRef {
    backend: "host-sqlite";
    /**
     * `eager` fsyncs each append. Costlier, but the only setting under which a
     * crash cannot lose the tail of a session.
     */
    flush?: "batched" | "eager";
}
/**
 * Serialisable Claude Agent SDK options.
 *
 * `version` is a literal so an older sidecar can reject a shape it does not
 * understand instead of silently ignoring half of it — the same reason
 * `ResolvedAgentExecutionSpec` carries `specVersion`.
 */
interface ClaudeAgentSdkOptionsV1 {
    version: 1;
    /**
     * The schema MUST be JSON Schema draft-07; the SDK rejects newer drafts. From
     * Zod: `z.toJSONSchema(s, { target: "draft-7" })`.
     */
    outputFormat?: {
        type: "json_schema";
        schema: Record<string, unknown>;
    };
    sessionId?: string;
    /** Resume the most recent session. Mutually exclusive with `resume`/`sessionId`. */
    continue?: boolean;
    /** Message uuid to resume *at*, for partial replay. */
    resumeSessionAt?: string;
    /**
     * Prompt uuid for the turn intentionally discarded by `resumeSessionAt`.
     * The SDK rejects the truncating resume when unrelated entries would also
     * be dropped, allowing callers to recover without silently losing history.
     */
    resumeDropsTurn?: string;
    persistSession?: boolean;
    title?: string;
    sessionStore?: ClaudeAgentSdkSessionStoreRef;
    /** Host-side warm-process pooling; not forwarded as an SDK `Options` field. */
    prewarm?: {
        enabled: boolean;
    };
    /**
     * File checkpointing. Requires user messages to carry uuids, which only
     * happens with `extraArgs: { 'replay-user-messages': null }` — the sidecar
     * adds that automatically rather than making every caller remember it.
     */
    enableFileCheckpointing?: boolean;
    /**
     * Skip ALL permission prompts. Honoured only when `permissionMode` is
     * `bypassPermissions` AND the host policy plus an explicit user confirmation
     * both allow it; otherwise the turn fails closed. Setting it here is a
     * request, never a grant.
     */
    allowDangerouslySkipPermissions?: boolean;
    permissionPromptToolName?: string;
    planModeInstructions?: string;
    plugins?: ClaudeAgentSdkPluginRef[];
    skills?: string[] | "all";
    toolAliases?: Record<string, string>;
    toolConfig?: {
        askUserQuestion?: {
            previewFormat?: "markdown" | "html";
        };
    };
    tools?: string[] | {
        type: "preset";
        preset: "claude_code";
    };
    /** MCP elicitation round-trips. */
    elicitation?: {
        enabled: boolean;
    };
    /** Runtime-initiated dialogs. `kinds` maps to `supportedDialogKinds`. */
    userDialog?: {
        enabled: boolean;
        kinds?: string[];
    };
    includeHookEvents?: boolean;
    agentProgressSummaries?: boolean;
    promptSuggestions?: boolean;
    taskBudget?: {
        total: number;
    };
    loadTimeoutMs?: number;
    sandbox?: ClaudeAgentSdkSandboxV1;
    betas?: string[];
    /**
     * Raw CLI flags. Deliberately last and deliberately narrow: only explicitly
     * reviewed, content-free flags are accepted. Every other flag could reach
     * SDK behaviour this contract does not model.
     */
    extraArgs?: Record<string, string | null>;
}

/**
 * Persisted step ids. `welcome` is included here (unlike Multica, which keeps
 * its intro out of the canonical order) because the mobile mode fork lives on
 * it — resuming a mobile user mid-flow has to be able to land back on the
 * screen where they picked standalone vs paired.
 */
type OnboardingStepId = "welcome" | "express" | "scan" | "provider" | "first-run";
/**
 * Which path through setup the user chose on the welcome screen.
 *
 *  - `express` — one screen that lists everything setup will do, does it on
 *    one press, and hands over the first task. Two screens end to end.
 *  - `custom`  — the four-step sequence, every choice left open.
 *
 * Undefined until the fork is answered, which is why {@link resolveOnboardingMode}
 * exists: a progress row written before this field did has to be readable, and
 * its `lastStep` is the only evidence of which path it was on.
 */
type OnboardingMode = "express" | "custom";
/**
 * How the user left the flow. Recorded so the post-onboarding "finish setup"
 * bar can say something specific, and so re-entry knows what is still missing.
 *
 *  - `completed`        — reached a first real output.
 *  - `provider_skipped` — left without any usable model access.
 *  - `runtime_skipped`  — skipped the scan step; no local runtime selected.
 *  - `task_failed`      — picked a starter card but the run errored out.
 *  - `legacy_dismissed` — migrated from the old `onboardingDismissedAt`
 *                         timestamp, whose true intent is unrecoverable. Never
 *                         re-prompts on its own; Settings offers a re-run.
 */
type OnboardingPath = "completed" | "provider_skipped" | "runtime_skipped" | "task_failed" | "legacy_dismissed";
/**
 * Completion bookkeeping. Classified `device-local`: every device legitimately
 * holds its own answer, because a phone's onboarding is substantially the
 * pairing flow. Syncing this would let a desktop completion mark an unpaired
 * phone as onboarded, stranding it in a state that is both "done" and unusable.
 */
interface OnboardingProgress {
    version: number;
    /** Set once the user reached a first real output. */
    completedAt?: string;
    /** Set when the user left early. Mutually exclusive with `completedAt`. */
    skippedAt?: string;
    /** Where to resume. Absent once `completedAt` is set. */
    lastStep?: OnboardingStepId;
    /**
     * Which path the user took. Device-local along with the rest of this record:
     * a phone's setup is substantially the pairing flow, and "I wanted to
     * configure my desktop by hand" says nothing about how it should ask on a
     * phone whose recommended path is two taps.
     */
    mode?: OnboardingMode;
    path: OnboardingPath;
    /** True once the user closed the residual "finish setup" bar for good. */
    finishBarDismissed?: boolean;
}
/**
 * What the user wants out of the product, inferred from which starter card
 * they picked rather than asked in a questionnaire — the card choice is the
 * intent declaration, and a behavioural signal beats a self-reported one.
 *
 * Mirrors the starter-card ids in `lib/onboarding/starter-cards.ts`.
 */
type OnboardingIntent = "read-folder" | "extract-text" | "summarize-web";
/**
 * Personalization. Classified `shared`: this is a statement about the person,
 * not the device, so moving to a second device should not re-ask it. Consumed
 * by the welcome-page starter samples and by the character preselect.
 */
interface OnboardingProfile {
    intent?: OnboardingIntent;
    /** Character the user ran their first output with. */
    characterId?: string;
}

/**
 * Compaction config resolved by `resolveSendOptions` and serialised onto
 * {@link SendOptions.compaction} for the sidecar. Every field is optional so an
 * absent blob falls back to the sidecar's built-in defaults. `summaryPrompt`
 * is composed in the renderer from the canonical summarizer prompt + the active
 * strategy + the user `focus`, so the sidecar never hard-codes wording.
 */
interface ResolvedCompaction {
    /** Whether automatic compaction runs (generic path). Default true. */
    enabled?: boolean;
    /** Window fraction (0..1) at which auto-compaction triggers. Default `AUTO_COMPACT_FRACTION`. */
    fraction?: number;
    /**
     * Authoritative context-window size (tokens) for the active model, resolved
     * from the provider catalog by `resolveSendOptions`. The generic (AI-SDK)
     * compaction trigger prefers this over its own conservative regex table, which
     * floors families like `deepseek*` at 128k and would otherwise auto-compact a
     * real 1M model (e.g. deepseek-v4) at ~107k. Absent ⇒ the sidecar falls back
     * to that table.
     */
    contextWindow?: number;
    /** Number of most-recent turns kept verbatim. Default 6. */
    keepRecent?: number;
    /** Free-form focus / compact instructions merged into the summary prompt. */
    focus?: string;
    /** Full summarization system prompt (canonical prompt + strategy + focus). */
    summaryPrompt?: string;
    /**
     * Hard cap on the summary call's output tokens (generic path). Mirrors
     * `CompressionModelConfig.maxSummaryTokens` (default 500). Without it the
     * summary inherits the full turn's (potentially large) output budget.
     */
    maxSummaryTokens?: number;
    /**
     * Alternate cheap/fast model for the summary call ONLY (generic path). Absent
     * ⇒ the sidecar reuses the turn's model + credentials. `model` alone (no
     * `protocol`/`credentials`) means "same provider, cheaper model". Credentials
     * are resolved in `resolveSendOptions` (async/registry), never in the pure
     * `resolveCompaction`. Treated like `providerCredentials` for log redaction.
     */
    summary?: {
        model?: string;
        protocol?: string;
        /**
         * Built-in provider id backing `credentials` (NOT the protocol). Set only
         * alongside `credentials`, i.e. when the summary runs on a DIFFERENT
         * provider than the turn; absent ⇒ the sidecar reuses the turn's provider
         * id along with its credentials. The sidecar needs the id — not just the
         * base URL — to pick the OpenAI endpoint family, since a responses-only
         * provider (codex) behind a relay preset is unidentifiable from its host.
         */
        providerId?: string;
        credentials?: {
            apiKey?: string;
            baseURL?: string;
            apiFlavor?: _cognia_provider_types_provider.ApiFlavor;
            headers?: Record<string, string>;
        };
        protocolAdapterSpec?: SendOptions["protocolAdapterSpec"];
    };
    /**
     * Compaction strategy (generic path): summary | sliding-window | selective |
     * hybrid | recursive. Drives `planStrategy` in the sidecar.
     */
    strategy?: CompressionStrategy;
    /** Trigger mode (generic path): token-threshold | message-count | manual. */
    trigger?: CompressionTrigger;
    /** Message-count trigger threshold (generic path, when trigger = message-count). */
    messageCountThreshold?: number;
    /** Keep ALL system messages verbatim (not just the leading block). */
    preserveSystemMessages?: boolean;
    /** When false, summarize deterministically (extractive) instead of an LLM call. */
    useAISummarization?: boolean;
    /** Importance score (0..1) above which a message is kept by the selective strategy. */
    importanceThreshold?: number;
    /** Per-tool-result token cap applied during compaction (default 500). */
    maxToolResultTokens?: number;
    /** Keep tool name/args/status metadata when capping a tool result. */
    preserveToolCallMetadata?: boolean;
