/**
 * The runtime adapter actually frozen into a spec. Unlike
 * {@link AgentRuntimePolicy} this includes `external`, which is never chosen
 * by policy directly — it is derived from an external-agent binding (teammate
 * runtime / preset) by the resolver.
 */
type AgentRuntimeAdapterId = "claude-agent-sdk" | "ai-sdk" | "external";
/**
 * Capability vocabulary for the compatibility matrix and the per-spec
 * effective set. "Hard" vs "preferred" is a property of the *request*
 * (`AgentExecutionPolicy.requires` / `prefers`), not of the id itself.
 */
type AgentCapabilityId = "streaming" | "session.multi-turn" | "session.resume" | "tools.ordinary" | "tools.parallel" | "tools.fragmented-json" | "tools.results" | "tools.errors" | "mcp" | "permissions.interrupt-resume" | "permissions.set-mode" | "prompt-caching" | "thinking" | "context-management" | "images" | "beta-features" | "rate-limit-handling" | "upstream-errors" | "stream-interruption" | "subagents.native" | "steer" | "set-model" | "checkpoint" | "compaction" | "output.structured" | "session.store" | "session.manage" | "permissions.update-rules" | "hooks.lifecycle" | "input.elicitation" | "input.dialog" | "plugins.native" | "skills.native" | "mcp.dynamic" | "subagents.manage" | "tasks.background" | "commands.dynamic" | "sandbox.native" | "observability.child" | "startup.prewarm";
/**
 * How well a runtime satisfies a capability.
 *
 * The distinction that matters is `equivalent`: an adapter that reaches the
 * same observable outcome by another mechanism (an AI SDK provider doing
 * structured output through its own schema path rather than the SDK's
 * `outputFormat`). Recording it as `native` would erase a real behavioural
 * difference; recording it as `unsupported` would fail a session that works.
 */
type AgentCapabilitySupport = "native" | "equivalent" | "unsupported";
/**
 * Per-capability verdict. `reason` is required for anything other than
 * `native` — an `unsupported` with no explanation is indistinguishable from an
 * unfinished adapter, and that ambiguity is what fail-closed exists to prevent.
 */
interface AgentCapabilityEvidence {
    support: AgentCapabilitySupport;
    reason?: string;
}
interface AgentModelBindings {
    primary: string;
    fast?: string;
    powerful?: string;
}
/**
 * The serialized projection of a {@link ResolvedAgentExecutionSpec} that rides
 * `SendOptions.execution` renderer → Rust (via the `extra` flatten) → sidecar.
 * The sidecar treats it as frozen: dispatch reads `runtimeAdapter` and never
 * re-derives the runtime from `provider`. Secrets (ticket secret, direct
 * credentials) are NOT here — they ride `SendOptions.env`.
 */
interface AgentExecutionSendSpec {
    specVersion: 1 | 2;
    executionFingerprint: string;
    runtimeAdapter: AgentRuntimeAdapterId;
    executionKind: "agent" | "completion";
    route: {
        kind: "gateway";
        endpoint: string;
        ticketId: string;
    } | {
        kind: "direct";
        credentialProfileRef?: string;
    };
    modelBindings: AgentModelBindings;
    capabilities: {
        effective: AgentCapabilityId[];
        disabledOptional: AgentCapabilityId[];
        /** v2+. Mirrors the resolved spec so the sidecar can fail closed too. */
        support?: Partial<Record<AgentCapabilityId, AgentCapabilityEvidence>>;
    };
    identity: {
        runId: string;
        parentRunId?: string;
        attemptId: string;
    };
    hostRef: string;
    /**
     * v2+. The turn's resolved composition axes (ADR-0117).
     *
     * Projected onto the wire so the sidecar can fail closed on its own side, in
     * the same spirit as `capabilities.support`. The concrete need is the Code
     * tool presentation: the sidecar decides which tool defs to register, so it
     * has to know whether this turn is `native`, `code`, or `both` — deriving
     * that from anything else would mean a second, drifting source of truth for
     * what the model is allowed to see.
     *
     * Only the axes are sent, never the prompt or tool text: the digests are
     * identity, not content. Absent means "native", which is the pre-ADR-0117
     * behaviour and the safe default.
     */
    composition?: AgentCompositionProjection;
}
/**
 * The wire-safe slice of `ResolvedAgentCompositionV1`.
 *
 * Deliberately a hand-written subset rather than the whole resolved object:
 * `warnings` is renderer-facing UI text, and shipping it would grow the
 * envelope with strings the sidecar has no use for.
 */
interface AgentCompositionProjection {
    authority: AgentPermissionMode;
    toolPresentation: ToolPresentationMode;
    orchestration: AgentOrchestrationPolicy;
    /** Identity of the composition, for correlating events and replay tapes. */
    compositionDigest: string;
    presetId: string;
}

/**
 * The permission modes a *user-selectable* composition may request.
 *
 * A deliberate subset of {@link AgentPermissionMode}, not a second union:
 * `dontAsk` and `auto` remain reachable programmatically (an Agent Team lead
 * may run a child at `dontAsk`) but are not offered as a mode axis, matching
 * the safety-ordered cycle in `components/chat/permission-mode-indicator.tsx`.
 */
type AgentAuthority = Extract<AgentPermissionMode, "plan" | "default" | "acceptEdits" | "bypassPermissions">;
/**
 * How tools are exposed to the model.
 *
 * `native` is one schema-described tool per capability. `code` exposes a single
 * `run_code` tool plus a typed SDK, so the model composes calls in a sandbox
 * instead of emitting one tool call per step. `both` offers each.
 *
 * `code` is read-only in the first release: only tools whose catalog entry sets
 * `programmaticReadOnly` are reachable from the SDK. That flag is a first-party
 * allowlist and is deliberately NOT derived from the MCP `readOnlyHint`
 * annotation, which third-party servers declare about themselves.
 */
type ToolPresentationMode = "native" | "code" | "both";
/**
 * How the turn is decomposed.
 *
 * `direct` is one agent loop. `subagent` allows delegation to children through
 * the SDK's own child-agent mechanism. `team` hands the turn to the Agent Team
 * lifecycle, which is a different runtime with its own gates and trajectory —
 * conflating it with `subagent` would make one value mean two schedulers.
 * `workflow` routes through the visual workflow engine. `verified-fresh-agent`
 * additionally requires an independent reviewer with its own context, which
 * may never inherit the producing agent's ceiling.
 *
 * `team` and `workflow` name *which* engine runs; the engine's target id
 * travels separately in `orchestrationRef`, because the id's storage of record
 * stays where it already lives (a conversation override's `teamId`, a
 * session's binding). A composition never becomes a second router.
 */
type AgentOrchestrationPolicy = "direct" | "subagent" | "team" | "workflow" | "verified-fresh-agent";
/**
 * How a run is attached to whoever asked for it.
 *
 * This is not "who executes" — that is orchestration. It is the difference
 * between an answer that comes back in the same breath, a task that detaches
 * and reports on its own, and work that leaves the machine entirely.
 *
 * `inline`     — the turn's reply is the answer. One request, one response.
 * `background` — the turn mints a durable ExecutionRun, acknowledges, reports
 *                milestones, and stays steerable and stoppable until it
 *                settles. Same executor as `inline` when orchestration is
 *                `direct`; only the attachment differs, which is exactly why
 *                this cannot be an orchestration value.
 * `human`      — no agent loop runs at all; the work is assigned to a person.
 */
type EngagementMode = "inline" | "background" | "human";
/**
 * How much a run may do before it owes a human a checkpoint.
 *
 * Authority answers "may the model call this tool, and does each call ask?".
 * Autonomy answers "does this *run* owe a human a checkpoint — before it
 * starts, before its product ships, on every turn?". Neither expresses the
 * other: no permission mode can say "run at full authority but hold the
 * finished reply for review", and no ceremony can say "this tool is off".
 *
 * The five levels map onto the IM connector's old three modes without loss:
 * `observe` was `manual`, `suggest` was `draft`, `act` was `auto`. `confirm`
 * and `autopilot` are the two rungs that mode stack never had.
 */
type AutonomyLevel = "observe" | "suggest" | "confirm" | "act" | "autopilot";

interface OutboundRequest {
    conversationRef: ConversationReference;
