    teammateId?: string;
    spawnPrompt?: string;
} | {
    kind: "tool_call";
    toolName: string;
    input: Record<string, unknown>;
} | {
    kind: "mcp_tool_call";
    serverId: string;
    toolName: string;
    input?: Record<string, unknown>;
