    /**
     * Create a platform chat through a RUNNING adapter that declares
     * `chat.create`. Member ids are canonical platform ids from
     * {@link resolveContacts} on the SAME adapter.
     */
    createChat(adapterId: string, input: CreateChatInput): Promise<CreateChatResult>;
    /** Rename / re-describe a chat (`chat.update`). */
    updateChat(adapterId: string, input: UpdateChatInput): Promise<void>;
    /** Invite members to a chat (`chat.members`). */
    addChatMembers(adapterId: string, input: ChatMembersInput): Promise<ChatMembersResult>;
    /** Remove members from a chat (`chat.members`). */
    removeChatMembers(adapterId: string, input: ChatMembersInput): Promise<ChatMembersResult>;
    /**
     * Resolve emails / phones / a free-text name query to canonical platform
     * member ids (`contact.resolve`). Gated `connectors:manage` (confirm
     * tier) because directory lookups expose personal contact data.
     */
    resolveContacts(adapterId: string, input: ResolveContactsInput): Promise<ContactCandidate[]>;
}

/**
 * Extended log levels with trace support
 */
type LogLevel = "trace" | "debug" | "info" | "warn" | "error" | "fatal";
type LogRuntime = "browser" | "server" | "tauri" | "mcp" | "plugin" | "internal" | "unknown";
type LogOrigin = "frontend" | "web-runtime" | "tauri" | "mcp" | "plugin" | "diagnostic" | "unknown";

/**
 * Log Entry Types
 */

/**
 * Structured log entry with full context
 */
interface StructuredLogEntry {
    /** Unique log entry ID */
    id: string;
    /** ISO timestamp */
    timestamp: string;
    /** Log level */
    level: LogLevel;
    /** Log message */
    message: string;
    /** Module/component name */
    module: string;
    /** Trace ID for request correlation */
    traceId?: string;
    /** Request ID for operation correlation */
    requestId?: string;
    /** Runtime execution ID */
    executionId?: string;
    /** Workflow ID (if applicable) */
    workflowId?: string;
    /** Workflow/runtime step ID */
    stepId?: string;
    /** Structured runtime event ID */
    eventId?: string;
    /** Machine-readable status/event code */
    code?: string;
    /** Runtime source (browser/tauri/native/etc) */
    runtime?: LogRuntime;
    /** Normalized origin classification for UI triage */
    origin?: LogOrigin;
    /** Session ID */
    sessionId?: string;
    /** Span ID for the operation this entry belongs to (see lib/logging/context.ts) */
    spanId?: string;
    /** Parent span ID (the enclosing span), when nested */
    parentSpanId?: string;
    /** Logical phase of the operation (e.g. "start", "end", "retry") */
    phase?: string;
    /** Retry attempt counter (1-based) */
    attempt?: number;
    /** Operation duration in milliseconds (stamped on span completion) */
    durationMs?: number;
    /** Additional structured data */
    data?: Record<string, unknown>;
    /** Error stack trace */
    stack?: string;
    /** Source file and line (dev only) */
    source?: {
        file?: string;
        line?: number;
        function?: string;
    };
    /** Tags for filtering */
    tags?: string[];
}

/**
 * Transport Types
 */

type TransportHealthStatus = "healthy" | "degraded" | "offline";
/**
 * Why a transport lost an entry. Closed on purpose.
 *
 * `droppedEntries` on its own is a number with no story: "the collector is
 * unreachable" and "we are producing faster than we can ship" and "the app
 * shut down mid-flush" all read as the same integer, so the number tells an
 * operator that something was lost but never what to do about it.
 *
 * - `ship-failed`        a flush to the destination failed outright.
 * - `overflow-evicted`   the buffer was full and older entries made way.
 * - `entry-rejected`     one entry could not be encoded or passed validation.
 * - `shutdown-discarded` the buffer was abandoned at shutdown or reset.
 * - `retention-pruned`   a retention sweep removed already-stored records.
 */
declare const LOG_DROP_REASONS: readonly ["ship-failed", "overflow-evicted", "entry-rejected", "shutdown-discarded", "retention-pruned"];
type LogDropReason = (typeof LOG_DROP_REASONS)[number];
/** Per-reason drop counts. Absent keys mean zero. */
type LogDropCounts = Partial<Record<LogDropReason, number>>;
interface TransportHealthSnapshot {
    transport: string;
    status: TransportHealthStatus;
    queueDepth: number;
    retryCount: number;
    /** Total entries lost. Always equals the sum of {@link droppedByReason}. */
    droppedEntries: number;
    /**
     * The same loss, attributed. Optional so a transport that has not adopted
     * the taxonomy still type-checks — but every transport in this repo does,
     * and `dropCountsSumTo` is the invariant that keeps the two agreeing.
     */
    droppedByReason?: LogDropCounts;
    lastSuccessAt?: string;
    lastFailureAt?: string;
    lastError?: string;
    updatedAt: string;
}

/**
 * Log Filter & Stats Types
 */

/**
 * Log filter options
 */
interface LogFilter {
    level?: LogLevel;
    module?: string;
    traceId?: string;
    spanId?: string;
    since?: Date;
    until?: Date;
    search?: string;
    tags?: string[];
    limit?: number;
    offset?: number;
}
/**
 * Log statistics
 */
interface LogStats {
    total: number;
    byLevel: Record<LogLevel, number>;
    byModule: Record<string, number>;
    oldestEntry?: Date;
    newestEntry?: Date;
}

/**
 * Agent-trace span persistence (Dexie v55).
 *
 * One row per finished span. The trace transport
 * (`lib/logging/transports/agent-trace-transport.ts`) is the only writer in
 * production; the hooks layer (`hooks/logging/use-agent-trace-logs.ts`,
 * `hooks/agent-trace/use-agent-trace-analytics.ts`) is the only reader.
 * Pattern mirrors `lib/db/session-usage.ts` — small focused functions, all
 * Dexie queries here so the rest of the app never opens the table directly.
 */

/** Richer per-window stats consumed by the agent-trace stats bar — adds
 * token / cache / cost breakdowns + per-model histogram on top of the
 * legacy `AgentTraceSessionAnalyticsSummary`. */
interface AgentTraceStatsSummary extends AgentTraceSessionAnalyticsSummary {
    totalSpans: number;
    totalInputTokens: number;
    totalOutputTokens: number;
    totalCacheReadTokens: number;
    totalCacheCreationTokens: number;
    /** `cacheReadTokens / (inputTokens + cacheReadTokens)` ∈ [0, 1]. 0 when no input tokens recorded. */
    cacheHitRate: number;
    errorCount: number;
    byModel: Record<string, {
        spans: number;
        inputTokens: number;
        outputTokens: number;
        costUsd: number;
    }>;
    bySurface: Record<string, number>;
}

/**
 * Trace-level rollups.
 *
 *  - `rollupTraces` groups the windowed spans by `traceId` into one row per
 *    trace for the "recent traces" table.
 *  - `buildWaterfall` turns one trace's spans (from
 *    `lib/db/agent-traces.ts:queryByTrace`, already oldest-first) into a
 *    parent/child tree with offset/width geometry for the Tempo-style drawer.
 */

interface TraceRollupRow {
    traceId: string;
    /** Name of the earliest-starting (root-ish) span. */
    rootName: string;
    startTime: number;
    /** Wall-clock span of the whole trace (last end − first start). */
    durationMs: number;
    spanCount: number;
    errorCount: number;
    totalCostUsd: number;
    surface: string;
}
interface WaterfallNode {
    span: AgentTraceSpan;
    label: string;
    depth: number;
    /** ms from trace start to this span's start. */
    offsetMs: number;
    /** this span's duration in ms (>= 0). */
    widthMs: number;
    isError: boolean;
    children: WaterfallNode[];
}
interface Waterfall {
    roots: WaterfallNode[];
    traceStart: number;
    traceEnd: number;
    totalMs: number;
}

/**
 * Serializers for taking one agent trace out of the app.
 *
 * A trace you can only look at is a trace you cannot escalate. These two
 * formats cover the realistic destinations:
 *
 *  - **JSON** — the raw `AgentTraceSpan[]` exactly as persisted. Round-trips
 *    into a bug report, a fixture, or a script.
 *  - **OTLP** — the same spans through `spansToOtlp`, the converter the
 *    `otlp-http` transport already uses. Drops straight into Jaeger, Tempo,
 *    Honeycomb, or anything else that speaks OTLP/HTTP JSON.
 *
 * Pure: no DOM, no filesystem, no `Date.now()`. The caller supplies the
 * timestamp for filenames so exports stay deterministic under test.
 *
 * Content previews (`inputPreview` / `outputPreview`) travel as persisted —
 * they only exist at all when the user enabled content capture and the
 * redaction gate passed, so re-filtering here would silently disagree with
 * what the UI already showed them. `redactPreviews` is offered for the case
 * where an export leaves the machine and the user wants them stripped anyway.
 */

type TraceExportFormat = "json" | "otlp";
interface TraceExportOptions {
    /** Drop `inputPreview` / `outputPreview` before serializing. */
    redactPreviews?: boolean;
}

/**
 * Lane model for the agent-trace timeline.
 *
 * The waterfall (`./trace-rollup.ts:buildWaterfall`) answers "what called
 * what" — one row per span, indented by parentage. It cannot answer "what was
 * this trace *doing* over its lifetime", because a chat turn with 20 tool
 * calls is 20 rows you have to scroll, and nothing shows that 18 of them ran
 * inside one model call.
 *
 * This module projects the same spans onto a small number of horizontal lanes
 * — model work, tool work, retrieval, and so on — so a whole trace fits in a
 * strip. It is the data behind `components/logging/trace-timeline.tsx`.
 *
 * Pure: no Dexie, no React, no `Date.now()`. Geometry is emitted as
 * percentages against an explicit window so the caller can zoom by narrowing
 * the window rather than by re-deriving anything.
 */

/**
 * How the horizontal axis is measured.
 *
 * - `duration` — real elapsed time. Truthful, but a trace with one 40s model
 *   call and 30 sub-millisecond tool calls renders as one bar and a smear.
 * - `sequence` — one equal slot per span in chronological order. Loses timing
 *   and shows structure: which lane was busy, in what order, how often.
 */
type TimelineScale = "duration" | "sequence";
/** What a lane collects. */
type TimelineGrouping = "operation" | "surface" | "model" | "agent";
interface TimelineWindow {
    since: number;
    until: number;
}
interface TimelineBlock {
    spanId: string;
    parentSpanId?: string;
    label: string;
    startTime: number;
    durationMs: number;
    /** Left edge, 0–100, against the active window. */
    offsetPct: number;
    /** Width, 0–100. Never 0 — a zero-duration span still has to be clickable. */
    widthPct: number;
    isError: boolean;
    /** Nesting depth within the trace, for subtle shading. */
    depth: number;
    costUsd: number;
    tokens: number;
    operationName: SpanOperationName;
}
interface TimelineLane {
    id: string;
    /** Display label. `operation`/`surface` ids are already human-readable; a
     * model or agent lane is labelled by its value. */
    label: string;
    blocks: TimelineBlock[];
    spanCount: number;
    errorCount: number;
    /** Summed span duration — can exceed the trace duration when work overlaps,
     * which is exactly the signal a lane header should carry. */
    busyMs: number;
    costUsd: number;
    tokens: number;
}
interface TimelineMarker {
    spanId: string;
    name: string;
    at: number;
    offsetPct: number;
}
interface TimelineTick {
    offsetPct: number;
    label: string;
    at: number;
}
interface TraceTimeline {
    lanes: TimelineLane[];
    /** The window the geometry is relative to. */
    window: TimelineWindow;
    /** Full trace bounds, regardless of the active window. */
    traceStart: number;
    traceEnd: number;
    totalMs: number;
    spanCount: number;
    errorCount: number;
    costUsd: number;
    tokens: number;
    markers: TimelineMarker[];
    ticks: TimelineTick[];
    scale: TimelineScale;
    grouping: TimelineGrouping;
}
interface BuildTimelineOptions {
    scale?: TimelineScale;
    grouping?: TimelineGrouping;
    /** Zoom. Omit for the full trace. Reversed bounds are normalized. */
    window?: TimelineWindow | null;
    /** Target number of axis ticks. */
    tickCount?: number;
}

/**
 * The coarse "how far back" window shared by the agent-trace surfaces.
 *
 * `AgentTraceStatsBar` owned this switch privately, which was fine while it was
 * the only consumer. The `/logs` Traces channel now drives the stats bar AND
 * the trace list from one control, and two copies of the same mapping would
 * drift the moment either grew a preset — so the mapping lives here and both
 * import it.
 *
 * Deliberately coarser than `./time-range.ts`: that module models the
 * observability dashboard's Grafana-style sliding presets (5m…30d) plus pinned
 * custom bounds and bucket sizing. This one is a four-way "today / week /
 * month / everything" picker with a calendar-aligned `today`, which the
 * dashboard has no notion of.
 *
 * Pure module — no Dexie, no React. `now` is injectable so tests are
 * deterministic.
 */
/** Coarse retention window for the agent-trace stats bar and trace list. */
type AgentTraceStatsWindow = "today" | "week" | "month" | "all";

/**
 * Plugin Logs & Agent-Trace API (`ctx.logs`) — the **read** side of
 * observability for monitoring, debugging, and cost-tracking plugins.
 *
 * Plugins have always been able to *write* logs (`ctx.logger`, a scoped
 * `@cognia/logging` logger). They had no way to read anything back: a plugin
 * that wanted to surface "your last run cost $2.10 and failed on the third
 * tool call" had to re-instrument the world, because the spans the app already
 * persists were host-private. This closes that gap.
 *
 * Two permissions, because the two halves carry different data:
 *
 *  - `logs:read` — the structured log stream, its stats, registered modules,
 *    and transport health. Operational metadata.
 *  - `trace:read` — agent-trace spans. Same rows the `/logs` Traces channel
 *    reads, and they may carry `inputPreview` / `outputPreview` — model input
 *    and output, captured only when the user enabled content capture and only
 *    after the redaction gate passed. Gating this separately means a cost
 *    dashboard can ask for spans without also getting the log firehose, and a
 *    log viewer never silently gains access to prompt text.
 *
 * Deliberately read-only. `clear()` / `deleteEntries()` exist on the transport
 * and are NOT exposed: a plugin must not be able to destroy the user's audit
 * trail. Emission stays on `ctx.logger`, which is already scoped to the plugin
 * so its output is attributable.
 */

interface PluginTraceListOptions {
    /** Retention window. Defaults to `today`. */
    window?: AgentTraceStatsWindow;
    /** Maximum traces returned, newest-first. Defaults to 50, capped at 500. */
    limit?: number;
    /** Keep only traces with at least one failed span. */
    errorsOnly?: boolean;
}
interface PluginTraceStatsOptions {
    window?: AgentTraceStatsWindow;
}
/**
 * Agent-trace reads (`ctx.logs.traces`). Every method is gated `trace:read`.
 */
interface PluginTraceAPI {
    /** One row per trace in the window, newest-first. */
    list(options?: PluginTraceListOptions): Promise<TraceRollupRow[]>;
    /** Every span of one trace, chronological. */
    spans(traceId: string): Promise<AgentTraceSpan[]>;
    /** Spans for one session, newest-first. */
    bySession(sessionId: string, limit?: number): Promise<AgentTraceSpan[]>;
    /** The parent/child waterfall tree with offset/width geometry. */
    waterfall(traceId: string): Promise<Waterfall>;
    /** The lane projection behind the `/logs` timeline strip. */
    timeline(traceId: string, options?: BuildTimelineOptions): Promise<TraceTimeline>;
    /** Cost / token / cache / error aggregates over a window. */
    stats(options?: PluginTraceStatsOptions): Promise<AgentTraceStatsSummary>;
    /**
     * Serialize one trace as raw span JSON or OTLP/HTTP JSON — the same bytes
     * the `otlp-http` transport streams, so a plugin can forward a trace to an
     * external backend without reimplementing the conversion. Pass
     * `{ redactPreviews: true }` to drop model input/output previews.
     */
    serialize(traceId: string, format?: TraceExportFormat, options?: TraceExportOptions): Promise<string>;
    /**
     * Fire for each batch of spans that lands after subscribing. Only spans the
     * handler has not already seen are delivered; the first tick is skipped so a
     * subscriber does not immediately receive history it did not ask for.
     * Returns a disposer.
     */
    subscribe(handler: (spans: AgentTraceSpan[]) => void): () => void;
}
interface PluginLogsAPI {
    /** Query the persisted structured log stream. Newest-first. */
    query(filter?: LogFilter): Promise<StructuredLogEntry[]>;
    /** Totals by level and module across the whole store. */
    stats(): Promise<LogStats>;
    /** Module names that have registered a logger this session. */
    modules(): string[];
    /** Serialize the (optionally filtered) stream as JSON. */
    export(filter?: LogFilter): Promise<string>;
    /**
     * Fire when a batch of log entries is flushed to storage, with the entries
     * written. Returns a disposer.
     */
    subscribe(handler: (entries: StructuredLogEntry[]) => void): () => void;
    /** Per-transport health snapshots (queue depth, retries, drops, last error). */
    transports(): Record<string, TransportHealthSnapshot>;
    /** Agent-trace reads. Gated separately — see the module docstring. */
    traces: PluginTraceAPI;
}

/**
 * Plugin Performance API (`ctx.perf`) — **read-only** access to the Rust
 * performance dashboard (ADR-0035) for monitoring / observability plugins.
 *
 * Wraps the `lib/perf/backend/commands.ts` seam. Deliberately read-only:
 * the sampler-control commands (`perfStartSampling` / `perfSetInterval` /
 * `perfStopSampling` / `perfResetHotspots` / `perfOpenTraceDir`) are NOT
 * exposed — a plugin shouldn't reconfigure the user's sampler or open OS
 * windows. Gated by `perf:read`. Desktop-only (inert empties on web).
 */

interface PluginPerfAPI {
    /** Recent ring-buffer samples + current sampler state. */
    snapshot(): Promise<PerfSnapshot>;
    /** Span hotspot rows (heaviest-first). */
    hotspots(): Promise<SpanSnapshot[]>;
    /** Static host + build details (`null` on web). */
    systemDetails(): Promise<SystemDetails | null>;
    /** Flight-recorder trace files on disk. */
    listTraces(): Promise<TraceFile[]>;
    /** Subscribe to live `perf://sample` frames. Returns a disposer. */
    subscribe(handler: (sample: PerfSample) => void): () => void;
}

/**
 * Script-type detection + run-request building for the integrated
 * terminal (ADR-0039).
 *
 * "Run this file in the terminal" needs to pick the right interpreter:
 * a `.sh` runs under bash, a `.ps1` under PowerShell `-File`, a `.py`
 * under `python3` (or `python` on Windows), etc. This module owns the
 * pure mapping — extension → interpreter, with a shebang taking
 * precedence — and turns it into a `SpawnRequest` the dock can spawn.
 *
 * Renderer-pure: no fs access. The caller supplies the optional shebang
 * line (read elsewhere) and platform; the Rust side validates the
 * interpreter binary exists at spawn time.
 */

interface ScriptType {
    /** Logical language/kind label (drives UI + telemetry). */
    kind: string;
    /** Interpreter binary to spawn. */
    interpreter: string;
    /** Args inserted before the script path (e.g. `-NoLogo -File` for ps1). */
    interpreterArgs: string[];
}

/**
 * Deterministic command-safety classifier — the "rules" tier of the agent
 * Auto-mode (`auto-mode.ts`). Given a command line it returns an
 * allow / ask / deny verdict purely from static rules, mirroring the
 * allowlist/blocklist/dangerous-pattern model the sidecar already ships for
 * `shell_execute_advanced` (`sidecar/builtin-tools/safety.mjs`) but richer:
 *
 *  - compound-command aware (via `splitCommandSegments`) — the worst verdict
 *    across the chain wins, and destructive commands hidden inside
 *    substitutions still surface;
 *  - subcommand aware for `git` / `npm`-family / `cargo`, so `git status`
 *    is allowed while `git push` asks;
 *  - privilege aware — a `sudo`-wrapped safe command escalates to `ask`;
 *  - catastrophe aware — `rm -rf /`, `dd of=/dev/…`, `mkfs`, pipe-to-shell,
 *    and fork bombs are denied outright.
 *
 * This is the fast, offline gate. When it returns `ask`, the orchestrator may
 * additionally consult the small-model judge (`command-judge.ts`). Pure: no
 * I/O, safe to run on every keystroke / tool call.
 */
type CommandVerdict = "allow" | "ask" | "deny";

/**
 * Plugin-contributed terminal completion providers (ADR-0039).
 *
 * A plugin can contribute Copilot-style command suggestions to the
 * integrated terminal in two ways:
 *
 *  1. **Declarative (manifest)** — `manifest.terminalCompletionProviders`
 *     lists lazy `{ id, label, entry, export }` factories. The
 *     `terminal-completion-bridge` imports each on plugin enable and
 *     registers the produced provider into the host completion registry.
 *
 *  2. **Imperative (runtime)** — `ctx.terminal.registerCompletionProvider(...)`
 *     (gated by `terminal:completion`) registers a provider on the fly.
 *
 * Both paths funnel through the same adapter so a plugin sees one provider
 * shape regardless of how it registered.
 */

/** Read-only context handed to a plugin completion provider. */
interface PluginTerminalCompletionContext {
    /** Terminal session id for providers that keep per-session caches. */
    sessionId: string;
    /** Shell family — `bash` | `zsh` | `pwsh` | `powershell` | `cmd` | `fish` | `nu` | `sh` | `unknown`. */
    shell: string;
    /** Raw shell binary path/name. */
    shellPath: string;
    /** Working directory, or null if unknown. */
    cwd: string | null;
    /** The partial command typed so far. */
    input: string;
    /** Cursor offset within `input`. */
    cursor: number;
    /** Recent command lines, oldest → newest. */
    recentCommands: string[];
    /** Platform hint. */
    platform: "windows" | "macos" | "linux" | "other";
    /** Owning project id, or null when the terminal is not project-scoped. */
    projectId?: string | null;
}
/** A single suggestion from a plugin provider. `text` is the FULL line. */
interface PluginTerminalCompletionItem {
    /** Full suggested command line (should start with the context input). */
    text: string;
    /** Short label shown beside the ghost text (e.g. "git", "npm"). */
    detail?: string;
    /** Longer explanation shown in the candidate popup. */
    description?: string;
    /** Optional confidence in [0,1]; defaults to 0.5 when omitted. */
    score?: number;
    /** Replace the input tail from `from` instead of only appending a suffix. */
    replace?: {
        from: number;
        insert: string;
    };
}
/** The provider object a plugin registers (runtime form). */
interface PluginTerminalCompletionProvider {
    /** Unique id within the plugin (namespaced with the plugin id by the host). */
    id: string;
    /** Human label for settings / source badge. */
    label: string;
    /** Lower runs first; default 100. */
    priority?: number;
    getCompletions(context: PluginTerminalCompletionContext, signal: AbortSignal): Promise<PluginTerminalCompletionItem[]> | PluginTerminalCompletionItem[];
}
/** Manifest declaration for a lazy completion provider. */
interface PluginTerminalCompletionProviderDef {
    /** Unique id within the plugin. */
    id: string;
    /** Human label. */
    label: string;
    /** Module path (relative to the plugin install root). */
    /**
     * Which runtime owns this factory. Omit to inherit the plugin type
     * (`python` plugins default to `"python"`); declaring `entry` pins it to
     * `"js"`. See {@link PluginContributionBackend}.
     */
    backend?: PluginContributionBackend;
    entry?: string;
    /** Named export = factory returning a `PluginTerminalCompletionProvider`. */
    export?: string;
    /** Lower runs first; default 100. */
    priority?: number;
}

/**
 * Plugin Terminal API (`ctx.terminal`) — imperative access to the
 * integrated terminal dock for plugins (build runners, dev-server
 * launchers, REPL bridges).
 *
 * Until now the dock was only reachable by the chat agent via the
 * synthetic `terminal_dock_*` MCP tools (`lib/terminal/dock-tool-handler.ts`),
 * gated by chat-session agent-trust. The `terminal:spawn|write|kill`
 * permissions existed but had no imperative surface. This wraps the same
 * dock primitives (`spawnFromDock` / `killFromDock` / the live
 * `TerminalSession`) so plugins can drive a real PTY in the user's dock.
 *
 * SAFETY:
 *  - Each spawned session is tagged with the plugin id (`extensionId`), so
 *    the dock shows it as plugin-owned and the store scopes visibility.
 *  - `write` / `kill` / `onData` / `readRecent` are **ownership-checked**:
 *    a plugin can only touch sessions IT spawned — never the user's tabs
 *    or another plugin's. This is the critical guard that makes a raw
 *    terminal surface safe to expose.
 *  - Permissions: `terminal:spawn` (create/list/read), `terminal:write`
 *    (pipe stdin), `terminal:kill` (terminate). All three are `DANGEROUS`.
 *  - Desktop/LAN-only — `spawnFromDock` returns an error when no PTY
 *    transport is available (plain browser).
 */

/** A plugin-contributed command-safety rule (`command-glob → verdict`). */
interface PluginCommandRule {
    /** Command glob; author with a trailing `*`, e.g. `"deploy-prod*"`. */
    pattern: string;
    /** Verdict applied when a command segment matches the glob. */
    verdict: CommandVerdict;
}
/** Result of `ctx.terminal.classifyCommand`. */
interface PluginCommandClassification {
    verdict: CommandVerdict;
    /** Short English rationale for the most severe finding. */
    reason: string;
    /** Head command that drove the verdict, when known. */
    matched?: string;
}
interface PluginTerminalSpawnOptions {
    /** Shell binary (absolute path or PATH name). Empty → host shell-detect. */
    shell?: string;
    /** Initial working directory. */
    cwd?: string;
    /** Project the tab belongs to (drives dock filtering). */
    projectId?: string;
    /** Extra environment variables. */
    env?: Record<string, string>;
    rows?: number;
    cols?: number;
    /** OSC-633 shell integration. Default true. */
    enableShellIntegration?: boolean;
}
interface PluginTerminalInfo {
    id: string;
    shell: string;
    cwd: string | null;
    status: "idle" | "running" | "exited";
}
interface PluginTerminalCommandRecord {
    cmd: string;
    exitCode: number | null;
    endedAt: number;
}
/** Options for `ctx.terminal.runScript`. */
interface PluginRunScriptOptions {
    /** Explicit interpreter override (bypasses extension/shebang detection). */
    interpreter?: string;
    /** Initial working directory. */
    cwd?: string;
    /** Arguments passed to the script (after its path). */
    args?: string[];
    /** Extra environment variables. */
    env?: Record<string, string>;
    rows?: number;
    cols?: number;
    /** Project the tab belongs to. */
    projectId?: string;
    /** First line of the file, if known — a `#!` shebang wins over the ext. */
    shebang?: string;
}
interface PluginTerminalAPI {
    /** Spawn a PTY in the dock, tagged to this plugin. Returns its id + shell. */
    spawn(options?: PluginTerminalSpawnOptions): Promise<{
        id: string;
        shell: string;
    }>;
    /**
     * Spawn a PTY that runs a script file under the correct interpreter
     * (`.sh`→bash, `.ps1`→pwsh -File, `.py`→python3, …). Tagged to this
     * plugin like `spawn`. Throws if the type can't be determined and no
     * `interpreter` override is given.
     */
    runScript(scriptPath: string, options?: PluginRunScriptOptions): Promise<{
        id: string;
        shell: string;
    }>;
    /** Resolve how a script path would be run, without spawning. */
    detectScriptType(scriptPath: string, shebang?: string): ScriptType | null;
    /** Pipe input into a session this plugin owns. */
    write(id: string, data: string | Uint8Array): Promise<void>;
    /** Terminate a session this plugin owns. */
    kill(id: string): Promise<void>;
    /** Subscribe to raw output bytes from a session this plugin owns. */
    onData(id: string, handler: (data: Uint8Array) => void): () => void;
    /** Recent command records for a session this plugin owns (default 10). */
    readRecent(id: string, lineLimit?: number): PluginTerminalCommandRecord[];
    /** List the sessions this plugin currently owns. */
    list(): PluginTerminalInfo[];
    /**
     * Contribute Copilot-style inline command suggestions to the integrated
     * terminal. The provider is namespaced with this plugin's id and tagged
     * as `plugin`-sourced. Returns a disposer; also auto-removed on plugin
     * disable. Requires `terminal:completion`.
     */
    registerCompletionProvider(provider: PluginTerminalCompletionProvider): () => void;
    /**
     * Contribute command-safety rules consulted by the agent's shell Auto-mode
     * (`lib/claude/permissions/auto-mode.ts`). Each rule maps a command glob to
     * an allow/ask/deny verdict; they sit BELOW the user's own
     * `agentPermissions.commandRules` in precedence, so a plugin can tighten or
     * loosen the policy for its own commands without overriding the user. The
     * rules merge across calls; returns a disposer (also dropped on plugin
     * disable). Requires `terminal:safety`.
     */
    registerCommandSafetyRule(rules: PluginCommandRule | PluginCommandRule[]): () => void;
    /**
     * Classify how risky a shell command is, using the same deterministic engine
     * Auto-mode uses (`classifyCommand`). Pure / read-only. Requires
     * `terminal:safety`.
     */
    classifyCommand(command: string): PluginCommandClassification;
}

/**
 * Plugin Subscription API — **read-only** access to the unified
 * subscription state (plan summaries + Anthropic usage metrics) for
 * usage-dashboard / cost-guard / quota plugins.
 *
 * SAFETY: this surface never exposes credentials. Specifically:
 *  - `getActiveAccountId` / `getActiveAccountSummary` return only the
 *    credential-free `AccountSummary` (id/label/plan/email/timestamps);
 *    the active snapshot's `env` array (which carries the resolved OAuth
 *    bearer for spawn) is dropped at the boundary.
 *  - usage snapshots have their `rawHeaders` (which can contain sensitive
 *    rate-limit / auth headers) and the internal Dexie `localId` stripped.
 *
 * There is no write surface — accounts/credentials are managed only through
 * the Settings UI. Gated by `subscription:read`.
 */

/** Usage snapshot with sensitive raw headers + internal key stripped. */
type PluginUsageSnapshot = Omit<UsageSnapshot, "rawHeaders">;
interface PluginSubscriptionAPI {
    /** Provider ids the host supports. */
    providers(): readonly ProviderId[];
    /** Credential-free account summaries for a provider. */
    listAccounts(provider: ProviderId): Promise<AccountSummary[]>;
    /** Active account id for a provider, or `null`. Never returns env/tokens. */
    getActiveAccountId(provider: ProviderId): Promise<string | null>;
    /** Summary of the active account for a provider (plan/email), or `null`. */
    getActiveAccountSummary(provider: ProviderId): Promise<AccountSummary | null>;
    /** Recent Anthropic usage snapshots (newest first), headers stripped. */
    getUsage(limit?: number): Promise<PluginUsageSnapshot[]>;
    /** The most recent usage snapshot, or `null`. */
    getLatestUsage(): Promise<PluginUsageSnapshot | null>;
    /** Subscribe to new usage samples. Returns a disposer. */
    onUsageUpdate(handler: (snapshot: PluginUsageSnapshot) => void): () => void;
}

/**
 * Guarded task-move semantics for the team task board (kanban).
 *
 * `canMoveTask` is the SINGLE source of truth for which status transitions a
 * human (or an actor on the human's behalf) may perform on a team task. It is
 * shared by:
 *   - the desktop board's drag-and-drop (illegal drop targets grey out at
 *     drag start via `allowedMoveTargets`),
 *   - the mobile board's action-sheet moves (Companion RPC `team_task_move`),
 *   - the plugin `ctx.team.moveTask` API.
 *
 * Ownership model behind the rules:
 *   - `blocked` is dependency-derived — cards enter/leave it automatically,
 *     never by hand.
 *   - `claimed` / `in_progress` belong to the runtime while a run is active
 *     (`executing` / `planning`); when the team is at rest they may be pushed
 *     back to `pending` (e.g. after a pause left them stranded).
 *   - `pending → cancelled` (drop a task), `review → completed | failed`
 *     (human review verdict), and `failed → pending` (manual retry,
 *     ADR-0022's deferred retry surface) are the human-owned transitions.
 *   - Same-column moves (reordering) are always allowed.
 */

/** Why a move was denied — keyed for i18n at the UI layer. */
type TaskMoveDenial = "blocked-column" | "runtime-owned" | "illegal-transition";
/** Store/RPC-level move failure: a guard denial or a missing task. */
type TaskMoveError = TaskMoveDenial | "task-not-found";

/**
 * Plugin Agent-Team API — lets plugins read the team task board (including
 * run-lifecycle observation: status / events / execution reports /
 * checkpoints) and perform guarded plan-level writes (feed tasks in from
 * external trackers, patch and assign them, manage the non-lead roster,
 * comment as a bot, move cards through the human-owned transitions).
 * Modeled on `goal-api.ts`.
 *
 * Design:
 *  - Reads/writes go through the `agent-team-store` — the single write
 *    source for teams/tasks (the same store the workspace kanban and the
 *    Companion RPCs use). No parallel data path.
 *  - `moveTask` is validated by the shared `canMoveTask` guard (via the
 *    store action), so a plugin can never push a transition the board UI
 *    would refuse; denials come back as `{ ok: false, reason }`.
 *  - Deliberately NO run control (`start`/`pause`/`resume`): starting a
 *    team consumes real tokens/compute — that stays a human (or Companion
 *    remote-control) decision. Plugins that need orchestration register
 *    workflow nodes / scheduler templates instead.
 *  - Gated by `team:read` (reads + subscribe) / `team:write` (mutations).
 */

interface PluginTeamTaskCreateInput {
    teamId: string;
    title: string;
    description?: string;
    priority?: SubAgentPriority;
    /** Teammate id — must belong to the team. */
    assignedTo?: string;
    tags?: string[];
    /** Upstream task ids that must complete first. */
    dependencies?: string[];
}
interface PluginTeamMoveResult {
    ok: boolean;
    reason?: TaskMoveError;
}
/**
 * Input for adding a teammate to an existing team. Plugins can only add
 * regular `"teammate"` members — the lead is synthesized at team creation
 * and is not a role a plugin may claim.
 */
interface PluginTeamTeammateCreateInput {
    teamId: string;
    name: string;
    description?: string;
    spawnPrompt?: string;
    /** Specialization blurb surfaced on the roster card. */
    specialization?: string;
}
/**
 * Whitelisted teammate patch — identity/prompt fields only. Run-owned fields
 * (`status` / `progress` / `currentTaskId` / token usage) are deliberately
 * excluded: those belong to the team runtime, exactly like the run-owned
 * task fields excluded from {@link PluginTeamTaskPatch}.
 */
interface PluginTeamTeammatePatch {
    name?: string;
    description?: string;
    spawnPrompt?: string;
    specialization?: string;
}
/**
 * Whitelisted task patch. Status transitions go through {@link PluginTeamAPI.moveTask}
 * (guarded); run-owned fields (`status` / `result` / `error` / `claimedBy` /
 * timing) are not patchable by plugins.
 */
interface PluginTeamTaskPatch {
    title?: string;
    description?: string;
    priority?: SubAgentPriority;
    tags?: string[];
    expectedOutput?: string;
    estimatedDuration?: number;
    /** Upstream task ids that must complete first. */
    dependencies?: string[];
}
/** Run-lifecycle snapshot for a team — status plus the latest execution report. */
interface PluginTeamRunStatus {
    teamId: string;
    status: TeamStatus;
    /** Latest unified execution report, or `null` before the first run. */
    report: TeamExecutionReport | null;
}
/** Agent-Team board API exposed to plugins. */
interface PluginTeamAPI {
    /** Every team (workspace-scoped store contents). */
    listTeams(): Promise<AgentTeam[]>;
    /** One team by id, or `null`. */
    getTeam(teamId: string): Promise<AgentTeam | null>;
    /** The team's roster. */
    listTeammates(teamId: string): Promise<AgentTeammate[]>;
    /** One teammate by id, or `null`. */
    getTeammate(teammateId: string): Promise<AgentTeammate | null>;
    /** The team's task board (unsorted; `order` is the column ordering). */
    listTasks(teamId: string): Promise<AgentTeamTask[]>;
    /**
     * Observe a team's board. Fires on any change to the team row, its
     * roster, or its tasks; returns an unsubscribe. Gated by `team:read`
     * at subscription time.
     */
    subscribe(teamId: string, listener: () => void): () => void;
    /**
     * Run-lifecycle snapshot: the team's `status` plus its latest execution
     * report. `null` when the team doesn't exist. Pull-style complement to the
     * `onTeam*` plugin hooks — usable by plugins that only hold `ctx.team`.
     */
    getRunStatus(teamId: string): Promise<PluginTeamRunStatus | null>;
    /**
     * The in-store run event ring buffer (last ~100 events, oldest first)
     * filtered to one team — task claims, completions, teammate lifecycle.
     */
    listEvents(teamId: string): Promise<AgentTeamEvent[]>;
    /** The latest unified execution report, or `null` before the first run. */
    getExecutionReport(teamId: string): Promise<TeamExecutionReport | null>;
    /** Progress-ledger checkpoints of the latest execution report (`[]` when none). */
    listCheckpoints(teamId: string): Promise<TeamExecutionCheckpoint[]>;
    /** Create a pending task on the board. */
    createTask(input: PluginTeamTaskCreateInput): Promise<AgentTeamTask>;
    /**
     * Patch a task's plan-owned fields (title / description / priority / tags /
     * expected output / estimate / dependencies). Run-owned fields are not
     * patchable — status goes through {@link moveTask}.
     */
    updateTask(taskId: string, patch: PluginTeamTaskPatch): Promise<AgentTeamTask>;
    /** Same-column reorder: place the task at `targetIndex` and renumber. */
    reorderTask(taskId: string, targetIndex: number): Promise<void>;
    /** Assign (or reassign) a task to a teammate on the same team. */
    assignTask(taskId: string, teammateId: string): Promise<void>;
    /** Append a comment to a task's board thread (author = the plugin). */
    addComment(taskId: string, text: string): Promise<AgentTaskComment | null>;
    /** Attach an artifact / file / link reference to a task. */
    attachTaskFile(taskId: string, attachment: Omit<TaskCommentAttachment, "id">): Promise<void>;
    /**
     * Move a task through the guarded board transitions (same `canMoveTask`
     * rules as the kanban drag). Never throws for a denial.
     */
    moveTask(taskId: string, to: TeamTaskStatus): Promise<PluginTeamMoveResult>;
    /** Add a regular teammate to the roster (never the lead). */
    addTeammate(input: PluginTeamTeammateCreateInput): Promise<AgentTeammate>;
    /** Patch a teammate's identity/prompt fields (whitelisted; never run state). */
    updateTeammate(teammateId: string, patch: PluginTeamTeammatePatch): Promise<AgentTeammate>;
    /**
     * Remove a teammate from the roster. Returns `false` (no-op) for the lead
     * or an unknown id — mirroring the store guard.
     */
    removeTeammate(teammateId: string): Promise<boolean>;
    /**
     * Replace the team's configuration (budget / governance / execution
     * pattern). Full-replace semantics, matching the store action; read the
     * current config via {@link getTeam} and patch client-side.
     */
    updateTeamConfig(teamId: string, config: AgentTeamConfig): Promise<void>;
}

/**
 * LLM extraction — turn a finished turn (rolling context + the new user/
 * assistant pair) into candidate durable memories. Reuses the shared
 * `LlmClient` contract and `extractJson` parser (`lib/twin/distill/llm.ts`).
 *
 * Mechanical re: trust: it only emits the types in `allowTypes`. The caller
 * (`run-memory-extraction`) sets `allowTypes` per provenance — e.g. it omits
 * `procedural` for anything not user/explicit, so a third-party message can
 * never produce a behavior-changing procedural memory. The prompt is also told
 * the allowed types so the model self-restricts.
 *
 * Fail-open: returns `[]` on any LLM / parse failure (memory is best-effort and
 * must never break the turn).
 */

interface MemoryCandidate {
    type: MemoryType;
    text: string;
    /** Model self-rated 1..10. */
    importance: number;
    /** Optional stable key (procedural dedupe / "always X"). */
    key?: string;
}

/**
 * LLM-judged consolidation (ADD / UPDATE / DELETE / CONFLICT / NOOP). For each
 * candidate, fetch the top-k semantically similar existing memories and let the
 * LLM choose ONE operation — solving dedupe, update, and contradiction in one
 * place instead of brittle rules.
 *
 * Contradictions never hard-delete: DELETE marks the old memory `invalidated`
 * and links `supersededById` (history preserved — Zep's "update, don't discard").
 * Borrows the cluster-prompt shape from `lib/twin/distill/agents/entity-merge-
 * agent.ts` and the version/ACL discipline from the agent-team shared-memory
 * orchestrator.
 *
 * Dependency-injected + fail-safe: a parse/LLM failure for a candidate defaults
 * to NOOP (never a destructive guess).
 */

type ConsolidationOp = {
    op: "ADD";
    memory: Memory;
    candidate: MemoryCandidate;
} | {
    op: "UPDATE";
    targetId: string;
} | {
    op: "DELETE";
    targetId: string;
} | {
    op: "CONFLICT";
    memory: Memory;
    targetId: string;
    candidate: MemoryCandidate;
} | {
    op: "NOOP";
};

/**
 * Shared deliberate-write path for the long-term memory store — the single
 * implementation behind every non-conversational write surface: the workflow
 * `action.memory.store` node, the plugin `ctx.memory.store` API, the MCP
 * bridge `memory_store` tool, and the companion RPC `memory_store` command.
 *
 * Mirrors the `/remember` explicit-capture contract: the text IS the memory
 * (no extraction LLM), but it still flows through the SAME consolidator so it
 * dedupes / updates / supersedes instead of blindly piling up. When no utility
 * LLM client is available it degrades to a direct Dexie insert + best-effort
 * vector upsert (`consolidated: false`) — the memory is never silently dropped.
 *
 * Trust model (ADR-0069):
 *   - `procedural` requires `user`/`explicit` provenance — API surfaces and
 *     automated workflows may not silently rewrite agent behavior.
 *   - The PII gate is mandatory. External surfaces get "block" only (they
 *     cannot consent to redaction on the user's behalf); the workflow node
 *     additionally supports "redact".
 *   - Policy blocks (disabled / temporary / PII) return a structured result;
 *     caller programming errors (empty text, bad scope combo, untrusted
 *     procedural) throw.
 */

type StoreMemoryCoreResult = {
    ok: true;
    /** False when the consolidator judged the fact already captured (NOOP). */
    stored: boolean;
    consolidated: boolean;
    /** The ADDed row's id (absent on UPDATE/NOOP outcomes). */
    memoryId?: string;
    applied: ConsolidationOp["op"][];
    piiRedacted?: boolean;
} | {
    ok: false;
    reason: "disabled" | "temporary" | "pii_blocked" | "policy_denied" | "scope_denied";
};
interface StoreExternalMemoryInput {
    text: string;
    /** External surfaces may only create semantic/episodic (never procedural). */
    type?: Extract<MemoryType, "semantic" | "episodic">;
    scope?: MemoryScope;
    characterId?: string;
    projectId?: string;
    agentId?: string;
    branch?: string;
    pathPattern?: string;
    key?: string;
    importance?: number;
    tags?: string[];
    source?: {
        sessionId?: string;
    };
    policyCharacterId?: string;
}

/**
 * Shared read path for external memory surfaces (plugin `ctx.memory.search`,
 * MCP `memory_search`, companion RPC `memory_search`). Thin, policy-aware
 * wrapper over `retrieveMemories`: it resolves the user's `MemoryConfig`,
 * enforces the `enabled` / `temporary` gates (temporary mode blocks reads too —
 * "the current context neither reads nor writes memory"), and threads the
 * configured `relevanceFloor` / `decayHalfLifeDays` / `enableQueryExpansion`
 * into the retriever the same way the chat injection path does.
 *
 * `touch` (accessCount / lastAccessedAt bump) stays ON by default so recency
 * reflects real usage regardless of surface; pass `touch: false` for
 * diagnostics-style reads that should not perturb decay.
 */

interface ExternalMemoryHit {
    memory: Memory;
    /** Normalized fused relevance in [0,1]. */
    relevance: number;
    /** Combined multi-factor score. */
    score: number;
}

/**
 * Shared mutation path for external memory surfaces (plugin `ctx.memory`
 * update/forget, MCP `memory_update`/`memory_forget`, companion RPC).
 *
 * - `updateExternalMemory`: patch text / importance / tags / key on an existing
 *   row. Text patches are PII-gated (block-only) and bump `version`; the vector
 *   doc is re-upserted best-effort so semantic search stays in sync.
 * - `forgetExternalMemory`: soft-invalidate (the consolidation-path contract —
 *   hard deletes stay user-panel-only). No PII risk, so it only requires
 *   `memory.enabled` (allowed even in temporary mode: forgetting reduces data).
 */
interface UpdateExternalMemoryPatch {
    text?: string;
    importance?: number;
    tags?: string[];
    key?: string;
    pinned?: boolean;
}
type MutateExternalMemoryResult = {
    ok: true;
} | {
    ok: false;
    reason: "disabled" | "temporary" | "pii_blocked" | "not_found" | "policy_denied" | "scope_denied";
};

/**
 * Plugin Memory API (`ctx.memory`) — lets plugins read and write the user's
 * autonomous long-term memory store (`lib/memory`, ADR-0069).
 *
 * Design:
 *  - Reads go through the shared external-search helper
 *    (`lib/memory/api/search-memory.ts`) / the `@/lib/db/memories` Dexie layer,
 *    honoring the user's `MemoryConfig` (`enabled` / `temporary` gates —
 *    blocked reads degrade to empty, matching how chat recall degrades).
 *  - Writes go through the shared external-write helpers
 *    (`lib/memory/api/store-memory.ts` / `mutate-memory.ts`): provenance is
 *    always `external` with `sourceChannel: "plugin"` + the plugin id stamped
 *    for the memory console; the PII gate is block-only (a typed
 *    `PluginPiiError` for plugin DX); `procedural` can never be created —
 *    plugins may not rewrite the agent's working instructions.
 *  - `forget` soft-invalidates (history preserved); hard deletes stay
 *    user-panel-only.
 *  - Gated by `memory:read` (reads) / `memory:write` (mutations).
 */

interface PluginMemorySearchOptions {
    /** Defaults to the user's configured `retrievalTopK`. */
    topK?: number;
    types?: MemoryType[];
    characterId?: string;
    projectId?: string;
    agentId?: string;
    branch?: string;
    path?: string;
    /** Default true; false = don't bump lastAccessedAt/accessCount. */
    touch?: boolean;
}
interface PluginMemoryListFilter {
    type?: MemoryType;
    scope?: MemoryScope;
    characterId?: string;
    projectId?: string;
    agentId?: string;
    branch?: string;
    pathPattern?: string;
    /** Defaults to `"active"`; pass `"invalidated"` to inspect history. */
    status?: MemoryStatus;
    /** Newest-first cap, default 100. */
    limit?: number;
}
type PluginMemoryStoreInput = Omit<StoreExternalMemoryInput, "source">;
/** Long-term memory API exposed to plugins. */
interface PluginMemoryAPI {
    /**
     * Hybrid (BM25 + vector) relevance search over active memories. Degrades to
     * `[]` when memory is disabled, temporary mode is on, or no backend exists.
     */
    search(query: string, opts?: PluginMemorySearchOptions): Promise<ExternalMemoryHit[]>;
    /** Newest-first listing (no relevance ranking). Empty when memory is off. */
    list(filter?: PluginMemoryListFilter): Promise<Memory[]>;
    /** Fetch one memory by id (undefined when missing or memory is off). */
    get(id: string): Promise<Memory | undefined>;
    /** Count of active memories in a scope (0 when memory is off). */
    count(scope?: MemoryScope, characterId?: string): Promise<number>;
    /**
     * Store one durable fact (semantic/episodic only). Consolidates against
     * existing memories when a utility LLM is available. Throws `PluginPiiError`
     * when the text trips the PII gate.
     */
    store(input: PluginMemoryStoreInput): Promise<StoreMemoryCoreResult>;
    /** Patch text / importance / tags / key. Text patches are PII-gated. */
    update(id: string, patch: UpdateExternalMemoryPatch): Promise<MutateExternalMemoryResult>;
    /** Soft-invalidate (kept for history; never a hard delete). */
    forget(id: string): Promise<MutateExternalMemoryResult>;
}

/**
 * Plugin Plan API — lets plugins read and drive `AgentPlan`s (ADR-0045).
 *
 * The plan hub is the app's canonical IR for multi-step agentic work, and it
 * was the only one of the three decompose-and-drive engines with no plugin
 * surface: `ctx.goals` and `ctx.team` shipped, `ctx.plans` did not — so a
 * plugin could start a goal or a team but could not see, approve, or run the
 * plan those very engines project into.
 *
 * Design (mirrors `goal-api.ts` deliberately):
 *  - Reads go straight to the `@/lib/db/plans` Dexie layer.
 *  - Mutations route through `getPlanRuntime()` so the runtime's side-effects
 *    fire (one-open-plan-per-session invariant, event log, abort registry,
 *    companion + scheduler + notification fan-out). Nothing is reimplemented.
 *  - Refinement needs a planner-capable LLM; the same renderer client the
 *    plan console uses is built here so plugins don't thread a model.
 *  - Gated by `plan:read` (reads) / `plan:write` (mutations).
 */

/** Plan authoring + driving API exposed to plugins. */
interface PluginPlanAPI {
    /** Fetch a plan by id, or `null` if it doesn't exist. */
    get(planId: string): Promise<AgentPlan | null>;
    /** All plans bound to a session (newest first). */
    listBySession(sessionId: string): Promise<AgentPlan[]>;
    /** Every plan across all sessions (bounded by `limit`, default 200). */
    listAll(limit?: number): Promise<AgentPlan[]>;
    /** The session's open plan (draft / awaiting approval / approved / live). */
    getOpenForSession(sessionId: string): Promise<AgentPlan | null>;
    /** The session's executing plan, if one is running. */
    getExecutingForSession(sessionId: string): Promise<AgentPlan | null>;
    /** The plan's lifecycle timeline, newest-last. */
    getEvents(planId: string, limit?: number): Promise<PlanEvent[]>;
    /** Create a plan. Replaces the session's existing open plan, as every producer does. */
    create(input: CreatePlanInput): Promise<AgentPlan>;
    /** Patch a not-yet-executing plan (title / description / steps / config). */
    updateDraft(planId: string, patch: UpdatePlanInput): Promise<AgentPlan | null>;
    /** Approve a plan for execution. */
    approve(planId: string): Promise<AgentPlan | null>;
    /** Reject a pending plan, recording optional feedback. */
    reject(planId: string, feedback?: string): Promise<AgentPlan | null>;
    /**
     * Start an approved plan. In-session plans return the turn the host should
     * send; orchestrated plans are started with {@link run}.
     */
    start(planId: string): Promise<{
        strategy: "in_session" | "orchestrated";
        status: PlanStatus;
    } | null>;
    /** Execute an approved plan through the orchestrated path (headless). */
    run(planId: string): Promise<{
        status: PlanStatus;
        output?: unknown;
    } | null>;
    /** Pause a running plan. */
    pause(planId: string): Promise<AgentPlan | null>;
    /** Resume a paused plan. */
    resume(planId: string): Promise<AgentPlan | null>;
    /** Cancel any non-terminal plan. */
    cancel(planId: string): Promise<AgentPlan | null>;
    /** Write one step's status (+ optional result summary). */
    setStepStatus(planId: string, stepId: string, status: PlanStepStatus, result?: string): Promise<AgentPlan | null>;
    /** Replan through the planner model (optimize / simplify / expand / reorder / repair). */
    refine(planId: string, type: PlanRefinementType, instructions?: string): Promise<AgentPlan | null>;
    /** Delete a plan and its events. */
    delete(planId: string): Promise<void>;
}

/** Claude Agent SDK 0.3.220 lifecycle events. */
type HookEvent = "PreToolUse" | "PostToolUse" | "UserPromptSubmit" | "Stop" | "Setup" | "SubagentStart" | "SubagentStop" | "SessionStart" | "SessionEnd" | "Notification" | "PreCompact" | "PostCompact" | "TaskCreated" | "TaskCompleted" | "PermissionRequest" | "PermissionDenied" | "WorktreeCreate" | "WorktreeRemove" | "FileChanged" | "DirectoryAdded" | "CwdChanged" | "InstructionsLoaded" | "ConfigChange" | "Elicitation" | "ElicitationResult" | "PostToolBatch" | "PostToolUseFailure" | "StopFailure" | "TeammateIdle" | "UserPromptExpansion" | "MessageDisplay";

/**
 * `ctx.hooks` — the plugin-facing view of the lifecycle-hook systems.
 *
 * Two things a plugin author could not do before this API existed:
 *
 *  1. **Know whether their hook is actually reachable.** Hooks are contributed
 *     by returning a `PluginHooks` object from `activate()`. Whether that
 *     object is live depends on the plugin's enabled state, and there was no
 *     way to ask. A plugin whose hook silently never fires had no diagnosis.
