 * There are two backends:
 *
 *   - `local`: Tauri Rust commands shell out to system `git` under the
 *     `<baseDir>/<repo>/<timestamp>` worktree, then `tokio::fs` cleans up.
 *   - `e2b`:   delegate to the e2b-sandbox plugin for cloud execution.
 *
 * Previously the `local` backend imported `simple-git` and `node:fs/promises`
 * directly, which dragged Node built-ins into the Next.js client bundle via
 * the plugin registry's static imports. The implementation now invokes Rust
 * commands (`github_workspace_*`), so the TS surface here is pure ESM — that
 * is what lets `next.config.ts` drop the `NODE_ONLY_MODULES` aliases.
 */
type WorkspaceBackend = "local" | "e2b";
interface WorkspaceHandle {
    backend: WorkspaceBackend;
    /** Filesystem path (local) or sandbox id (e2b). */
    path: string;
    /** Repo this workspace was cloned from. */
    repoFullName: string;
    /** Branch checked out. */
    branch: string;
    /** Trusted source branch used to create the isolated target branch. */
    baseBranch?: string;
    /** Wall clock ms when allocated. */
    createdAt: number;
}
/**
 * Pluggable E2B backend. A repository Integration plugin may wire a real
 * implementation backed by the `e2b-sandbox` plugin when present.
 * Tests inject fakes.
 */
interface E2BBackend {
    clone(opts: {
        repoFullName: string;
        branch: string;
        token: string;
    }): Promise<WorkspaceHandle>;
    commitAndPush(opts: {
        workspace: WorkspaceHandle;
        message: string;
        remoteBranch?: string;
    }): Promise<string>;
    remove(handle: WorkspaceHandle): Promise<boolean>;
}

/**
 * Type contracts for plugin-contributed workspace backends.
 *
 * A "workspace backend" is the execution sandbox the GitHub-delivery
 * issue-loop and similar agentic flows clone repos / run commands inside.
 * Today there are two built-ins — local git checkout (Tauri Rust commands)
 * and the e2b-firecracker sandbox (contributed by `plugins/e2b-sandbox/`).
 * This type set is the declarative contract plugins target; the former
 * `setE2BBackend` global singleton setter has been removed.
 *
 * Two registration paths, mirroring `plugin-ocr.ts`:
 * - **Manifest** `manifest.workspaceBackends[]` — lazy factory.
 * - **Imperative** `ctx.workspace.registerBackend(backend)` in `activate()`.
 *
 * Both flow through `lib/github/workspace-backend-registry.ts`. The host
 * resolves a backend by its unprefixed kind (`resolveWorkspaceBackendByKind`),
 * so plugin-namespaced ids stay reachable.
 *
 * Permission gate: `process:spawn` + `filesystem:write`. See ADR-0026.
 *
 * NOTE — the runtime shape of a backend (`clone / commitAndPush / remove`)
 * is identical to the existing `E2BBackend` interface in
 * `lib/github/workspace.ts`. We re-export it as `WorkspaceProvider` here
 * so plugin authors get a type name that doesn't collide with the
 * pre-existing `WorkspaceBackend = "local" | "e2b"` string union.
 */

/**
 * One backend contribution in `manifest.workspaceBackends[]`. Lazy factory
 * shape — `entry` is dynamic-imported only when the registry first needs
 * the backend.
 */
interface PluginWorkspaceBackendDef {
    /**
     * Backend id, unprefixed. The registry prefixes with the plugin id at
     * registration time (`<pluginId>:<id>`) so two plugins cannot collide;
     * the host still finds it by kind (`resolveWorkspaceBackendByKind("e2b")`).
     */
    id: string;
    /** Human label for picker UI. */
    label: string;
    /**
     * Which runtime owns this backend's factory. Omit to inherit the plugin type
     * (`python` plugins default to `"python"`); declaring `entry` pins it to
     * `"js"`. See {@link PluginContributionBackend}.
     */
    backend?: PluginContributionBackend;
    /** Relative path inside the plugin install root. Required for JS backends. */
    entry?: string;
    /** Named export resolving to `PluginWorkspaceBackendFactory`. JS only. */
    export?: string;
    /** Short description shown in the workspace picker. */
    description?: string;
}
interface PluginWorkspaceBackendRegistration {
    backendId: string;
    unregister(): void;
}

interface WorkspaceEntry {
    /** Path relative to the search root, normalised to forward slashes. */
    relPath: string;
    absolutePath: string;
    isDir: boolean;
    size: number;
    /** Last-modified time in ms since epoch, or `null` when unavailable. */
    mtimeMs: number | null;
}

/** What a recursive walk found, and what it withheld. */
interface WorkspaceWalkResult {
    entries: WorkspaceEntry[];
    /** A cap stopped the walk before the tree was exhausted. */
    truncated: boolean;
    /** Files refused by the host's sensitive-name floor (`.env`, `id_rsa`, …). */
    skippedSensitive: number;
}
interface WorkspaceWalkOptions {
    relPath?: string;
    includeIgnored?: boolean;
    /** Include directories as well as files. Default: files only. */
    includeDirs?: boolean;
    /** Entry cap. Default 5 000, hard ceiling 50 000. */
    maxEntries?: number;
    /** Directory depth. Default 24. */
    maxDepth?: number;
}

/**
 * Turns a repository reference into a checkout a plugin can read.
 *
 * `ctx.workspace` was a registration-only API: a plugin could contribute a
 * backend and read back one it had registered itself, and there was no way for
 * anyone to *obtain* a checkout. The three mechanisms that could produce one —
 * `cloneToWorkspace` (github.com `owner/repo` only, host-internal), `git_clone`
 * (any URL, no guard rails, not on `ctx.git`) and the task-workspace worktree
 * manager (needs a local repo already) — returned three incompatible handles
 * and none was reachable from a plugin. This is the missing consumer side.
 *
 * Containment, deliberately narrower than "any path the process can read":
 *
 * - a **remote** is cloned into the plugin's own data directory, so it cannot
 *   collide with another plugin's checkout and uninstalling reclaims the disk;
 * - a **local path** must be inside a root the user has already opened. A
 *   plugin naming an arbitrary directory would be the filesystem escape that
 *   `ctx.fs` (jailed to the plugin's data dir) and `ctx.git` (locked to the
 *   Source Control root) both exist to prevent. To document another
 *   repository, the user opens it.
 */

/** How the caller named the repository. */
type WorkspaceAcquireSpec = {
    kind: "current-project";
} | {
    kind: "local-path";
    path: string;
} | {
    kind: "git-url";
    url: string;
    ref?: string;
    allowedHosts?: string[];
}
/** Whatever the user typed — resolved by {@link parseRepoSpec}. */
 | {
    kind: "auto";
    input: string;
    allowedHosts?: string[];
};
interface PluginWorkspaceHandle {
    /** Absolute filesystem root of the checkout. */
    root: string;
    origin: "current-project" | "local-path" | "clone";
    /** Set when the checkout came from a remote. */
    remote?: {
        host: string;
        owner: string;
        repo: string;
        url: string;
        ref?: string;
    };
    /** True when the checkout is ours to delete. */
    ephemeral: boolean;
    /**
     * Commit the checkout was at when it was acquired. Absent when the path is
     * not a git repository, or when this runtime has no git bridge.
     *
     * The point of recording it here is that `changedSince` becomes answerable:
     * a caller that stored the ref knows a later empty diff means "nothing
     * changed", not "I asked about a ref the host could not resolve". Without
     * it those two answers are the same empty array.
     */
    headRef?: string;
}

/**
 * Plugin Workspace Backend API.
 *
 * Lets a plugin contribute an issue-loop / sandbox-runner backend to the
 * shared `workspace-backend-registry`. Plugins call
 * `ctx.workspace.registerBackend(...)` from `activate()`, or declare
 * `manifest.workspaceBackends[]` and let `workspace-backend-bridge.ts`
 * resolve the lazy factory on plugin enable.
 *
 * Backend ids are namespaced as `<pluginId>:<backendId>`. The host dispatches
 * on the unprefixed *kind* via `resolveWorkspaceBackendByKind` (e.g.
 * `cloneToWorkspace({ backend: "e2b" })` finds `cognia-e2b-sandbox:e2b`), so
 * plugins never need to know how the host names backends. ADR-0026 §2 §D.
 *
 * Auto-cleanup on plugin disable is wired through
 * `clearWorkspaceBackendsForPlugin(pluginId)`.
 *
 * The API also has a *consumer* half (`acquire` / `walk` / `read` /
 * `changedSince`), added with ADR-0145. Registration alone left the contract
 * half-built: a plugin could contribute a backend and read back one it had
 * registered itself, and nothing anywhere let it obtain a checkout to work in.
 * See `lib/plugin/workspace/acquire.ts` for the containment rules.
 */

interface PluginWorkspaceAPI {
    /**
     * Register a workspace backend. The given id is prefixed with the plugin
     * id to avoid collisions across plugins. Throws if the same plugin tries
     * to register two backends with the same unprefixed id.
     *
     * The optional `label` / `description` show up in the workspace picker
     * UI (when one ships — the registry already tracks these fields).
     */
    registerBackend(args: {
        id: string;
        label: string;
        description?: string;
        backend: E2BBackend;
    }): PluginWorkspaceBackendRegistration;
    /**
     * Resolve a backend this plugin registered, by its unprefixed id. The
     * lookup auto-applies the `<pluginId>:` namespace, so a plugin that called
     * `registerBackend({ id: "sandbox" })` reads it back with
     * `getBackend("sandbox")`. Without this, plugin-contributed backends were
     * registered under the prefixed id but the host only ever resolved the
     * legacy unprefixed `"e2b"`, leaving them unreachable. Returns `undefined`
     * when the plugin never registered that id.
     */
    getBackend(id: string): E2BBackend | undefined;
    /** Snapshot of backend ids this plugin has registered. */
    listRegistered(): string[];
    /**
     * Obtain a checkout to read.
     *
     * A remote is cloned into this plugin's own data directory under guard rails
     * (https only, host allow-list, shallow, timed, size bounded). A local path
     * must be inside a workspace the user has already opened — a plugin naming
     * an arbitrary directory is the filesystem escape the rest of the plugin API
     * is built to prevent.
     */
    acquire(spec: WorkspaceAcquireSpec): Promise<PluginWorkspaceHandle>;
    /**
     * Enumerate the checkout's files, honouring `.gitignore`.
     *
     * Check `truncated` before treating the result as complete, and
     * `skippedSensitive` to know the host withheld credential files.
     */
    walk(handle: PluginWorkspaceHandle, options?: WorkspaceWalkOptions): Promise<WorkspaceWalkResult>;
    /** Read one file; pass `ref` to read it at a revision instead of on disk. */
    read(handle: PluginWorkspaceHandle, relPath: string, options?: {
        maxBytes?: number;
        ref?: string;
    }): Promise<string | null>;
    /** Repo-relative paths that differ between `ref` and the current revision. */
    changedSince(handle: PluginWorkspaceHandle, ref: string): Promise<string[]>;
    /**
     * Discard a handle. Deletes the checkout only when this plugin cloned it;
     * a handle onto the user's own project is left alone. Resolves `false` when
     * there was nothing to delete, so releasing twice is not an error.
     */
    release(handle: PluginWorkspaceHandle): Promise<boolean>;
}

/**
 * Type contracts for plugin-contributed OCR providers.
 *
 * Plugins extend `lib/ocr/` by registering a custom `OcrProvider` either:
 * 1. **Declaratively** via `manifest.ocrProviders[]` — the host's
 *    `lib/plugin/bridge/ocr-providers-bridge.ts` dynamic-imports each `entry`
 *    on plugin enable and calls the named `export` to produce the provider.
 * 2. **Imperatively** via `ctx.ocr.registerProvider(provider)` in
 *    `activate()` — useful when the provider needs state from `ctx.config`
 *    or `ctx.secrets`.
 *
 * Both paths funnel through the same `lib/ocr/registry.ts:registerOcrProvider`
 * singleton so the auto-router and Dexie cache see the new provider exactly
 * like a built-in. Registration is auto-revoked on plugin disable.
 *
 * The `provider.ocr` runtime point lives in
 * `lib/plugin/contracts/plugin-points.ts:CANONICAL_RUNTIME_POINTS` and is
 * permission-gated by `network:fetch` (most providers reach a cloud API).
 *
 * See ADR-0026.
 */

/**
 * One OCR provider contribution in `manifest.ocrProviders[]`.
 *
 * The host loads the provider lazily — `entry` is dynamic-imported only when
 * the OCR registry first needs a provider not yet resolved. Plugins should
 * therefore avoid heavy module-level work in the entry file.
 */
interface PluginOcrProviderDef {
    /**
     * Provider id, unprefixed. The host prefixes with the plugin id at
     * registration time (`<pluginId>:<id>`) so two plugins cannot collide.
     */
    id: string;
    /**
     * Human-readable name shown in OCR settings and the auto-router debug panel.
     */
    label: string;
    /**
     * Which runtime owns this provider's factory. Omit to inherit the plugin
     * type (`python` plugins default to `"python"`); declaring `entry` pins it
     * to `"js"`. See {@link PluginContributionBackend}.
     */
    backend?: PluginContributionBackend;
    /**
     * Relative path inside the plugin install root to the module that exports
     * the factory. Validated by `lib/plugin/core/validation.ts` against path
     * traversal (no `..`, no absolute paths, no NUL bytes).
     *
     * Required for JS-backed providers; omitted for python-backed ones, which
     * resolve through the `plugin_python_call` seam instead of a JS module.
     */
    entry?: string;
    /**
     * Named export on the entry module — must resolve to a
     * `PluginOcrProviderFactory` at runtime. Required for JS-backed providers.
     */
    export?: string;
    /**
     * Free-text description displayed in the provider picker UI.
     */
    description?: string;
}
/**
 * Handle returned by `ctx.ocr.registerProvider(...)`. Calling `unregister()`
 * is idempotent — the host already unregisters on plugin disable.
 */
interface PluginOcrRegistration {
    /** Prefixed provider id (`<pluginId>:<id>`). */
    providerId: string;
    unregister(): void;
}

/**
 * Plugin OCR Provider API.
 *
 * Lets a plugin contribute a custom `OcrProvider` to the shared OCR
 * registry (`lib/ocr/registry.ts:registerOcrProvider`). Plugins call
 * `ctx.ocr.registerProvider(provider)` from `activate()`, or declare
 * `manifest.ocrProviders[]` and let `lib/plugin/bridge/ocr-providers-bridge.ts`
 * register on enable.
 *
 * The registration handle is auto-revoked when the plugin is disabled
 * (`clearOcrProvidersForPlugin(pluginId)`), so manual cleanup is
 * belt-and-braces.
 *
 * Provider ids are namespaced as `<pluginId>:<providerId>` to prevent
 * collisions with built-ins and across plugins. The registry's internal
 * duplicate check fires if the same plugin tries to register twice.
 *
 * See ADR-0026 §2 §A.
 */

interface PluginOcrAPI {
    /**
     * Register a custom OCR provider. The given `providerId` is prefixed with
     * the plugin id before reaching the underlying registry. Returns a handle
     * with an `unregister()` method (idempotent — the host also auto-cleans
     * on plugin disable).
     *
     * Throws if the plugin has already registered a provider with the same
     * unprefixed id.
     */
    registerProvider(provider: OcrProvider): PluginOcrRegistration;
    /** Snapshot of provider ids this plugin has registered. */
    listRegistered(): string[];
}

/**
 * Plugin Workflow Template Definitions.
 *
 * Plugins contributing the `workflow-template` capability ship complete visual
 * workflow blueprints (nodes + edges + settings) through the manifest. The host
 * registers each entry into the `workflow-template-registry` overlay on enable
 * and unregisters on disable — identical lifecycle to `agent-team-template`
 * (ADR-0032). Templates surface in the editor's Settings tab → "Plugins &
 * capabilities" and instantiate into a fresh `VisualWorkflow` via
 * `projectPluginWorkflowTemplate`.
 *
 * The `requires` block declares cross-capability dependencies; missing ones
 * become non-blocking warnings (mirrors the agent-team-template `requires`
 * pattern). Unlike teams, workflow templates can also depend on plugin-
 * contributed node/trigger kinds — declared as the runtime-PREFIXED kind
 * (`<pluginId>.<kind>`), which is how `lib/plugin/core/context.ts:prefixKind`
 * names them in the catalog + executor registry.
 */

/**
 * Cross-capability dependencies declared by a plugin workflow template. Each
 * id list points into another overlay registry (or, for the workflow-specific
 * lists, the node-executor / trigger registries + plugin catalog).
 */
interface WorkflowTemplateRequires {
    /** Skill ids contributed by other plugins (consumed by `action.skill.invoke`). */
    skillIds?: string[];
    /** MCP server preset ids (consumed by `action.mcp.invokeTool`). */
    mcpServerPresetIds?: string[];
    /** Native Anthropic tool ids. */
    nativeAnthropicToolIds?: string[];
    /** Subagent ids: built-in names or `<pluginId>:<subagentId>`. */
    subagentIds?: string[];
    /** Plugin node kinds the template uses — declared PREFIXED (`<pluginId>.<kind>`). */
    pluginNodeKinds?: string[];
    /** Plugin trigger kinds the template uses — declared PREFIXED (`<pluginId>.<kind>`). */
    pluginTriggerKinds?: string[];
}
/** A graph node in a template blueprint. Mirrors the author-supplied fields of
 * `WorkflowNode` (the runtime adds ids/timestamps at instantiation time). */
interface PluginWorkflowTemplateNode {
    id: string;
    /** Node kind — built-in (`action.character.send`) or plugin (`<pluginId>.<kind>`). */
    type: string;
    typeVersion: number;
    position: {
        x: number;
        y: number;
    };
    data: {
        label: string;
        params?: Record<string, unknown>;
        notes?: string;
    };
}
/** A graph edge in a template blueprint. Mirrors `WorkflowEdge`. */
interface PluginWorkflowTemplateEdge {
    id: string;
    source: string;
    sourceHandle?: string;
    target: string;
    targetHandle?: string;
    label?: string;
    data?: {
        kind?: "default" | "conditional" | "parallel" | "loop" | "error";
    };
}
/** Category mirrors the editor's template-picker buckets. */
type PluginWorkflowTemplateCategory = "automation" | "integration" | "ai" | "data" | "github" | "general";
/**
 * Plugin-contributed visual workflow template — a self-contained blueprint
 * (distinct from the host `WorkflowTemplate`, which points at a stored
 * `workflowId`).
 */
interface PluginWorkflowTemplateDef {
    /** Unique id within the plugin. Runtime template id is `<pluginId>:<id>`. */
    id: string;
    /** Display name shown in the template list. */
    name: string;
    /** One-line description. */
    description: string;
    /** Template category — drives sorting/filtering. */
    category: PluginWorkflowTemplateCategory;
    /** Lucide icon name shown on the template card. */
    icon?: PluginIconName;
    /** Optional complexity hint (matches `VisualWorkflow.complexity`). */
    complexity?: "starter" | "intermediate" | "advanced";
    /** The blueprint's nodes. */
    nodes: PluginWorkflowTemplateNode[];
    /** The blueprint's edges. */
    edges: PluginWorkflowTemplateEdge[];
    /** Default run-settings overrides merged over the host defaults. */
    settings?: Partial<WorkflowSettings>;
    /**
     * Cross-capability dependencies. Missing dependencies surface as warnings via
     * `validateWorkflowTemplateRequires(def)` — non-blocking.
     */
    requires?: WorkflowTemplateRequires;
}

/**
 * Canonical, framework-free platform capability vocabulary (ADR 0060 — L0).
 *
 * A capability is a coarse, declarative answer to "can this runtime do X?"
 * that workflow nodes (and, later, placement/routing) can require without
 * branching on `isTauri()` ad hoc. This module is the SINGLE source of truth
 * for the vocabulary and for "what can the local runtime do" — device-to-hub
 * reporting (`device_capabilities_report`) and node requirements
 * (`NodeCatalogEntry.requires`) both speak these ids.
 *
 * Pure leaf: imports only `./detect`, no React and no `@/lib/tauri` /
 * `@/lib/capacitor`, so non-React `lib/` code and hooks can both depend on it
 * without circular imports — same discipline as `detect.ts`.
 */

/**
 * Core capability ids. Extend deliberately — every id here is wire format
 * (persisted on `pairedDevices` rows and stamped into workflow node
 * `requires`), so ids are append-only and never renamed.
 *
 * - `shell`             — can spawn one-shot OS processes (git, scripts).
 * - `pty`               — has the integrated PTY-backed terminal.
 * - `sidecar`           — runs the Node sidecar (Claude host, builtin tools).
 * - `keyring`           — OS keyring access for `keyring:*` secret refs.
 * - `uia-automation`    — desktop UI automation (screenshot, click, UIA events).
 * - `ocr`               — native OCR pipeline.
 * - `camera` / `geolocation` / `barcode-scan` / `voice-record` / `share-sheet`
 *                       — Capacitor-native mobile facilities.
 * - `push-display`      — can surface push/local notifications to a human.
 * - `biometric`         — biometric prompt available.
 * - `webview`           — an interactive webview UI is attached.
 * - `browser`           — an Agent-operable browser engine is ready.
 * - `headless`          — runs without an interactive UI (ADR 0059 cloud
 *                         brain; assigned to no webview platform here).
 * - `always-on`         — process hosts long-lived listeners that outlive the
 *                         page (Rust cron daemon, webhook receiver).
 * - `connector-runtime` — platform connector adapters run here.
 * - `mcp-runtime`       — MCP client/server stack runs here.
 * - `pro-ide`           — can host the embedded code-server "Pro IDE"
 *                         (ADR-0088). Coarse like its neighbours: listed for
 *                         the desktop shell, while `codeserver_supported()`
 *                         still answers the per-OS/arch question at call time.
 */
declare const CORE_CAPABILITY_IDS: readonly ["shell", "pty", "sidecar", "keyring", "uia-automation", "ocr", "camera", "geolocation", "barcode-scan", "voice-record", "share-sheet", "push-display", "biometric", "webview", "browser", "headless", "always-on", "connector-runtime", "mcp-runtime", "pro-ide", "thread-handoff-v1"];
type CoreCapabilityId = (typeof CORE_CAPABILITY_IDS)[number];
/**
 * Full capability id space: core ids plus `plugin:<pluginId>` tags a plugin
 * may declare for its own nodes ("this node needs my plugin active here").
 */
type CapabilityId = CoreCapabilityId | `plugin:${string}`;

/**
 * Type contracts for plugin-contributed workflow extensions.
 *
 * Plugins extend the visual workflow editor in two ways:
 * 1. Custom **node executors** (`PluginNodeDef`) — appear in the editor's
 *    Sidebar palette under a "Plugin nodes" group, scheduled by the
 *    orchestrator like any built-in.
 * 2. Custom **trigger sources** (`PluginTriggerDef`) — produce
 *    `TriggerEvent`s that wake workflows. The plugin owns the lifecycle
 *    of the long-running listener via `start` / `stop`.
 *
 * The runtime registers these via `PluginContext.workflow.register*`
 * (see `lib/plugin/core/context.ts`). Both definition kinds live behind
 * the `extension:workflow` permission gate — declared in
 * `lib/plugin/contracts/plugin-points.ts:CANONICAL_RUNTIME_POINTS`.
 *
 * See ADR 0017 for the full design.
 */

/** Node executor function — same shape as built-in node executors. */
type PluginNodeExecuteFn = (ctx: StepExecutionContext) => Promise<StepExecutionResult>;
/**
 * A node definition the plugin contributes to the workflow editor catalog.
 * `kind` is automatically prefixed with `<pluginId>.` at registration time
 * to prevent collisions, so plugin authors should provide a short
 * unprefixed identifier (e.g., `"action.fetchPage"`).
 */
interface PluginNodeDef {
    /** Unprefixed kind (e.g. `"action.fetchPage"`). Runtime prefixes pluginId. */
    kind: string;
    /** Definition version — bump when params schema changes incompatibly. */
    typeVersion: number;
    /**
     * Editor category. Most plugin nodes use `"plugin"` so they land in the
     * dedicated "Plugin nodes" group; advanced authors can pick a built-in
     * category to interleave with the host's nodes.
     */
    category: WorkflowNodeCategory | "plugin";
    /**
     * Display name in the catalog (palette / inspector / canvas). Used verbatim
     * as the fallback. To LOCALIZE it, ship `manifest.i18n.locales.<locale>` with
     * the UNPREFIXED key `"workflow.nodes.<kind>.label"` (the host prefixes it to
     * `plugin.<pluginId>.workflow.nodes.<kind>.label`, where `<kind>` is THIS
     * `kind` field). The editor resolves that overlay key per the active locale
     * and falls back to this string when no translation is registered. See
     * `lib/workflow/i18n/node-translate.ts:pluginNodeMessageKey`.
     */
    label: string;
    /**
     * Short description shown in the catalog tooltip / inspector. Localize via
     * the UNPREFIXED key `"workflow.nodes.<kind>.description"` (same scheme as
     * `label` above).
     */
    description: string;
    /** lucide-react icon name; falls back to `Box` when missing. */
    iconName: PluginIconName;
    /** Search keywords beyond label/description. Optional. */
    keywords?: string[];
    /**
     * JSON Schema describing the node's params. Drives the auto-generated
     * inspector form when the plugin doesn't supply a custom config component.
     */
    paramsSchema: Record<string, unknown>;
    /** Default param values inserted when the node is dropped on the canvas. */
    defaultParams?: Record<string, unknown>;
    /** Marks the node as desktop-only; the editor shows a `Desktop` badge. */
    desktopOnly?: boolean;
    /**
     * Platform capabilities the executor needs at run time (ADR 0060) — see
     * `lib/platform/capabilities.ts`. Checked by the orchestrator's capability
     * preflight; without it a bare `desktopOnly` maps to `["shell"]`.
     */
    requires?: readonly CapabilityId[];
    /** Whether the orchestrator should retry on transient failure. Default true. */
    retryable?: boolean;
    /** Per-node timeout (ms). Falls back to the workflow's default. */
    timeoutMs?: number;
    /** The actual executor invoked by the orchestrator. */
    execute: PluginNodeExecuteFn;
}
/**
 * Lifecycle handle returned by `PluginTriggerDef.start`. The host calls
 * `stop()` when the trigger is unregistered (plugin disable, workflow
 * delete, host shutdown). Stop must be idempotent.
 */
interface PluginTriggerHandle {
    stop(): Promise<void> | void;
}
interface PluginTriggerStartContext {
    /** The workflow this trigger feeds. */
    workflowId: string;
    /** Exact trigger-node root this live source instance feeds. */
    triggerId: string;
    /** Workflow author's per-instance trigger params. */
    params: Record<string, unknown>;
    /**
     * Emit a trigger event. The host wraps this into a full `TriggerEvent`
     * and dispatches it to the orchestrator (and, in headless mode, the
     * Rust scheduler).
     */
    emit(payload: unknown): void;
